-- ===========================================================================
-- THE RESIDENT — FUNCTION DEFINITIONS (generated)
-- ===========================================================================
--
-- GENERATED BY scripts/sync-functions.sh. Do not hand-edit: run the script
-- again instead. It asks Postgres for the exact definition of every
-- Resident-owned function and writes it out verbatim, because most of these
-- are SECURITY DEFINER — they run as their owner, so RLS does not constrain
-- them and the body is the only thing standing between a caller and the
-- data. Hand-copying that is how a one-character difference becomes a
-- security hole.
--
-- Apply AFTER the theresident_schema_part*.sql files: these depend on the tables.
--
-- Everything here is CREATE OR REPLACE, so applying it to a database that
-- already has them changes nothing.
--
-- WHY THIS FILE FINALLY EXISTS. For most of this project 75 of the database's
-- functions lived in production and in no file here — created in the Supabase
-- dashboard during feature work and never brought back. docs/DISASTER-RECOVERY
-- said so plainly: a rebuild from the schema of record was missing behaviour
-- it would not complain about, including res_notify and every maintenance
-- sweep. The schema would restore, the app would come up, and things would
-- quietly not happen.
--
-- Captured 13 September 2026: 168 functions, read from the live catalogs.
-- ===========================================================================

-- Bodies are not validated as they are created. pg_dump does the same thing,
-- for the same reason: these functions call each other, a dump has no reliable
-- dependency order to emit them in, and without this the first function that
-- references a later one aborts the whole file. res_distance_m is the one that
-- surfaced it here.
--
-- The cost is that a body referencing something that does not exist is no
-- longer caught at apply time. The restore drill's own verification step is
-- what covers that instead — it checks the functions are present and callable
-- after the rebuild, which is the question that actually matters.
set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.ensure_res_profile()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid();
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF;
  INSERT INTO public.profiles (id) VALUES (uid) ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.res_profiles (id, role) VALUES (uid, 'resident')
    ON CONFLICT (id) DO NOTHING;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.res_account_ready(p_user uuid, p_min_hours integer, p_require_verified boolean)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from profiles
     where id = p_user
       and created_at <= now() - (p_min_hours || ' hours')::interval
       and (not p_require_verified or is_verified = true)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.res_ack_area_broadcast(p_broadcast uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into res_area_broadcast_receipts (broadcast_id, user_id, seen_at, acknowledged_at)
  values (p_broadcast, auth.uid(), now(), now())
  on conflict (broadcast_id, user_id)
  do update set acknowledged_at = coalesce(res_area_broadcast_receipts.acknowledged_at, now()),
                seen_at = coalesce(res_area_broadcast_receipts.seen_at, now());
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_ack_broadcast(p_broadcast uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  insert into res_org_broadcast_receipts (broadcast_id, user_id, seen_at, acknowledged_at)
  values (p_broadcast, auth.uid(), now(), now())
  on conflict (broadcast_id, user_id)
  do update set acknowledged_at = coalesce(res_org_broadcast_receipts.acknowledged_at, now()),
                seen_at = coalesce(res_org_broadcast_receipts.seen_at, now());

  update notifications
     set read = true, is_read = true, read_at = now()
   where recipient_id = auth.uid()
     and type = 'res_org_broadcast'
     and data->>'broadcast_id' = p_broadcast::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_add_room_occupant(p_room uuid, p_tenant uuid, p_occupant_name_raw text, p_rent_amount numeric, p_notes text)
 RETURNS res_room_occupants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_room_occupants;
begin
  if not public.res_owns_room(p_room) then raise exception 'not_your_room'; end if;
  if p_tenant is null and coalesce(trim(p_occupant_name_raw), '') = '' then
    raise exception 'occupant_identity_required: give a name, or link a resident';
  end if;

  insert into res_room_occupants (room_id, tenant_id, occupant_name_raw, rent_amount, notes)
  values (p_room, p_tenant, nullif(trim(coalesce(p_occupant_name_raw, '')), ''), p_rent_amount,
          nullif(trim(coalesce(p_notes, '')), ''))
  returning * into v_row;

  update res_rooms set status = 'occupied' where id = p_room;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_advertise_room(p_room uuid)
 RETURNS res_listings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room res_rooms;
  v_property res_properties;
  v_listing res_listings;
begin
  perform public.res_check_rate_limit('advertise_room', 20, 86400);
  if not public.res_owns_room(p_room) then raise exception 'not_your_room'; end if;

  select * into v_room from res_rooms where id = p_room;
  if v_room.listing_id is not null then
    raise exception 'already_advertised';
  end if;

  select * into v_property from res_properties where id = v_room.property_id;

  insert into res_listings (
    landlord_id, title, description, price, currency, location, suburb,
    images, property_id
  ) values (
    auth.uid(), v_room.label,
    coalesce(v_room.advantages, '') ||
      case when v_room.disadvantages is not null then E'\n\n' || v_room.disadvantages else '' end,
    coalesce(v_room.price, 0), v_room.currency, coalesce(v_property.address, ''),
    coalesce(v_property.suburb, ''), coalesce(v_room.photos, '{}'), v_room.property_id
  )
  returning * into v_listing;

  update res_rooms set listing_id = v_listing.id where id = p_room;

  return v_listing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_alert_reach_preview(p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_suburb text DEFAULT NULL::text, p_community uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_count integer;
begin
  if v_me is null then raise exception 'not signed in'; end if;

  select count(distinct uid) into v_count from (
    select cm.user_id as uid
      from res_community_members cm
     where p_community is not null and cm.community_id = p_community

    union

    select rp.id
      from res_profiles rp
     where p_suburb is not null and rp.suburb is not null
       and lower(rp.suburb) = lower(p_suburb)

    union

    select ha.user_id
      from res_home_areas ha
     where p_lat is not null and p_lon is not null
       and public.res_distance_m(ha.lat, ha.lon, p_lat, p_lon) <= 3000
  ) t
  where uid is not null and uid <> v_me;

  return coalesce(v_count, 0);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_approve_request(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req record; v_title text;
begin
  select * into v_req from res_room_requests where id = p_request;
  if v_req is null then raise exception 'request not found'; end if;
  if v_req.landlord_id <> auth.uid() then raise exception 'not your listing'; end if;

  update res_room_requests set status = 'approved' where id = p_request;

  -- #34.3 one room, one tenant
  update res_room_requests
     set status = 'rejected'
   where listing_id = v_req.listing_id and id <> p_request and status = 'pending';

  -- #9: one tenant, one landlord — close out every OTHER request this tenant
  -- holds anywhere else, pending or already (wrongly) approved.
  update res_room_requests
     set status = case when status = 'approved' then 'ended' else 'rejected' end
   where tenant_id = v_req.tenant_id
     and id <> p_request
     and status in ('pending', 'approved');

  -- #34.4
  update res_listings set status = 'taken' where id = v_req.listing_id
  returning title into v_title;

  perform res_notify(v_req.tenant_id, 'res_request_approved',
    'Your application was approved', coalesce(v_title, 'The room is yours'),
    jsonb_build_object('listing_id', v_req.listing_id, 'request_id', p_request));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_approve_unit_verification(p_unit uuid, p_jurisdiction uuid, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_level text;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if not public.res_is_platform_admin() then raise exception 'not_a_platform_admin'; end if;
  select level into v_level from res_jurisdictions where id = p_jurisdiction;
  if v_level is null then raise exception 'unknown_jurisdiction'; end if;
  update res_org_units set verified = true, jurisdiction_id = p_jurisdiction where id = p_unit;
  if not found then raise exception 'unknown_unit'; end if;
  update res_unit_verification_requests
     set status = 'approved', decided_by = v_uid, decided_at = now(),
         decision_note = nullif(trim(p_note), '')
   where unit_id = p_unit and status = 'pending';
  insert into res_org_unit_audit (unit_id, action, actor_id, detail)
  values (p_unit, 'verified', v_uid, nullif(trim(p_note), '')),
         (p_unit, 'jurisdiction_bound', v_uid, v_level);
  begin
    perform public.res_ensure_area_probation(p_unit);
  exception when undefined_function then null;
  end;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_area_billing_state(p_unit uuid)
 RETURNS TABLE(state text, plan text, days_remaining integer, allows_routine boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    case
      when b.unit_id is null then 'none'
      when b.status = 'exempt' then 'exempt'
      when b.status = 'active'
        and (b.current_period_end is null or b.current_period_end > now()) then 'active'
      when b.status = 'probation' and b.probation_ends_at > now() then 'probation'
      else 'lapsed'
    end as state,
    b.plan,
    case
      when b.status = 'probation' and b.probation_ends_at > now()
        then greatest(0, ceil(extract(epoch from (b.probation_ends_at - now())) / 86400)::integer)
      when b.status = 'active' and b.current_period_end is not null
        then greatest(0, ceil(extract(epoch from (b.current_period_end - now())) / 86400)::integer)
      else null
    end as days_remaining,
    (b.unit_id is not null and (
       b.status = 'exempt'
       or (b.status = 'active' and (b.current_period_end is null or b.current_period_end > now()))
       or (b.status = 'probation' and b.probation_ends_at > now())
    )) as allows_routine
  from (select p_unit as unit_id) k
  left join res_org_unit_billing b on b.unit_id = k.unit_id
  where public.res_user_is_sender_of_or_above(p_unit, auth.uid());
$function$
;

CREATE OR REPLACE FUNCTION public.res_area_broadcast_block_reason(p_unit uuid, p_target geography)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_unit res_org_units;
  v_boundary geography;
begin
  select * into v_unit from res_org_units where id = p_unit;
  if not found then
    return 'unknown_unit';
  end if;
  if not coalesce(v_unit.verified, false) then
    return 'not_verified';
  end if;
  if v_unit.jurisdiction_id is null then
    return 'no_jurisdiction';
  end if;
  select boundary into v_boundary from res_jurisdictions where id = v_unit.jurisdiction_id;
  if v_boundary is null then
    return 'no_jurisdiction';
  end if;
  if p_target is null then
    return 'no_target';
  end if;
  if not ST_Covers(v_boundary::geometry, p_target::geometry) then
    return 'outside_jurisdiction';
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_area_broadcast_history(p_unit uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, unit_id uuid, unit_name text, target_label text, priority text, category text, title text, body text, recipient_count integer, sent_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b.id, b.unit_id, u.name, b.target_label, b.priority, b.category,
         b.title, b.body, b.recipient_count, b.sent_at
  from res_area_broadcasts b
  join res_org_units u on u.id = b.unit_id
  where p_unit is null or b.unit_id = p_unit
  order by b.sent_at desc
  limit 100;
$function$
;

CREATE OR REPLACE FUNCTION public.res_area_daily_cap(p_level text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_level
    when 'ward' then 10
    when 'service_area' then 10
    when 'municipality' then 6
    when 'district' then 4
    when 'province' then 3
    when 'national' then 2
    else 4
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_area_place_names(p_target geography)
 RETURNS TABLE(suburbs text[], cities text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce(array_agg(distinct h.suburb) filter (where h.suburb is not null and trim(h.suburb) <> ''), '{}'),
    coalesce(array_agg(distinct h.city) filter (where h.city is not null and trim(h.city) <> ''), '{}')
  from res_home_areas h
  where p_target is not null
    and ST_Covers(p_target, ST_MakePoint(h.lon, h.lat)::geography);
$function$
;

CREATE OR REPLACE FUNCTION public.res_area_plan_for_level(p_level text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_level
    when 'ward' then 'area_ward'
    when 'service_area' then 'area_institution'
    when 'municipality' then 'area_municipal'
    when 'district' then 'area_municipal'
    when 'province' then 'area_provincial'
    when 'national' then 'area_national'
    else 'area_institution'
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_auto_return_tools()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  with done as (
    update res_tool_library
       set status = 'available', rented_by = null, rented_until = null
     where status = 'pending_return' and updated_at < now() - interval '72 hours'
    returning 1
  ) select count(*) into v_count from done;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_award_good_neighbour(p_user_id uuid, p_xp integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_xp < 0 or p_xp > 100 then
    raise exception 'invalid xp amount';
  end if;
  perform public.award_xp(p_user_id, p_xp);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_block_user(p_blocked uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_blocked = auth.uid() then raise exception 'cannot block yourself'; end if;
  insert into res_blocks (blocker_id, blocked_id) values (auth.uid(), p_blocked)
  on conflict do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_book_seat(p_lift_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_seats integer;
begin
  perform public.res_check_rate_limit('lift_book', 30, 3600);
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  update res_lift_clubs
     set available_seats = available_seats - 1
   where id = p_lift_id
     and available_seats > 0
  returning available_seats into v_seats;

  if v_seats is null then
    if not exists (select 1 from res_lift_clubs where id = p_lift_id) then
      raise exception 'lift not found';
    end if;
    raise exception 'no seats available';
  end if;

  return v_seats;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_borrow_tool(p_tool uuid, p_until date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid; v_title text;
begin
  update res_tool_library
     set status = 'rented', rented_by = auth.uid(), rented_until = p_until
   where id = p_tool and status = 'available'
  returning owner_id, title into v_owner, v_title;

  if v_owner is null then raise exception 'tool_unavailable'; end if;

  perform res_notify(v_owner, 'res_dispatch', 'Your tool was borrowed', v_title,
                     jsonb_build_object('tool_id', p_tool));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_broadcast_alert(p_alert_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_alert record;
  v_recipients uuid[];
  v_key text;
  v_url text;
begin
  select * into v_alert from res_alerts where id = p_alert_id;
  if not found then
    raise exception 'alert not found';
  end if;

  -- Everyone who plausibly shares this neighbourhood, by any signal actually
  -- held. Deliberately a UNION of weak signals rather than one strict rule:
  -- for a safety alert, reaching someone slightly too far away is a far
  -- smaller harm than reaching nobody.
  --
  -- is_verified is NOT a condition. Verification is a trust signal for
  -- transactions; it has no business deciding who gets warned about danger,
  -- and requiring it made the alert reach exactly one account.
  select array_agg(distinct uid) into v_recipients from (
    -- 1. Members of the community the alert was raised in.
    select cm.user_id as uid
      from res_community_members cm
     where v_alert.community_id is not null
       and cm.community_id = v_alert.community_id

    union

    -- 2. Residents whose own suburb matches. res_profiles.suburb is
    --    Resident-owned; profiles.city, which the old query used, is empty
    --    for every account in the database.
    select rp.id
      from res_profiles rp
     where v_alert.suburb is not null
       and rp.suburb is not null
       and lower(rp.suburb) = lower(v_alert.suburb)

    union

    -- 3. Residents whose saved home area is within 3km of the alert.
    --    This is what res_home_areas was built for.
    select ha.user_id
      from res_home_areas ha
     where v_alert.lat is not null and v_alert.lon is not null
       and public.res_distance_m(ha.lat, ha.lon, v_alert.lat, v_alert.lon) <= 3000
  ) t
  where uid is not null and uid <> v_alert.user_id;

  if v_recipients is null or array_length(v_recipients, 1) is null then
    return;
  end if;

  insert into notifications (recipient_id, actor_id, type, title, body, data)
  select r, v_alert.user_id, 'res_alert_panic',
         '🚨 NEIGHBOURHOOD ALERT: ' || v_alert.title,
         v_alert.description,
         jsonb_build_object('alert_id', v_alert.id, 'kind', v_alert.kind)
  from unnest(v_recipients) as r;

  -- Push, so the alert reaches a phone with the app closed — which is the
  -- state every phone is in, most of the time. Wrapped so a push failure can
  -- never undo an alert already delivered in-app. Still requires
  -- VAPID_PRIVATE_KEY on the edge function; until that is set this degrades
  -- to in-app only rather than erroring.
  begin
    select decrypted_secret into v_key
      from vault.decrypted_secrets where name = 'service_role_key';

    if v_key is not null then
      v_url := 'https://feevvddvrjmfbhffccbf.supabase.co';
      perform net.http_post(
        url := v_url || '/functions/v1/web-push-send',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_key
        ),
        body := jsonb_build_object(
          'userIds', to_jsonb(v_recipients),
          'title', '🚨 ' || v_alert.title,
          'body', coalesce(v_alert.description, 'A neighbour has raised an alert nearby.'),
          'url', '/dashboard/community?tab=safety&alert=' || v_alert.id::text,
          'tag', 'alert-' || v_alert.id::text,
          -- A panic alert stays on screen until acknowledged.
          'requireInteraction', true
        )
      );
    end if;
  exception when others then
    null;
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_bump_reputation(p_user uuid, p_points integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user is null or p_points is null or p_points <= 0 then return; end if;

  insert into res_reputation (user_id, score, last_action_at)
  values (p_user, p_points, now())
  on conflict (user_id) do update
    set score = res_reputation.score + p_points,
        last_action_at = now();

  -- One reputation across both apps (CONTRACT.md §8)
  perform public.res_award_good_neighbour(p_user, least(p_points, 100));
exception when others then
  -- Reputation must never block the action that earned it
  null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_can_broadcast_to_area(p_unit uuid, p_target geography)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from res_org_units u
    join res_jurisdictions j on j.id = u.jurisdiction_id
    where u.id = p_unit
      and u.verified = true
      and p_target is not null
      -- ::geometry deliberate — on geography, polygon-covers-polygon is not
      -- reliably supported (a geography polygon does not cover itself), which
      -- would silently refuse "send to my whole ward". Do not simplify back.
      and ST_Covers(j.boundary::geometry, p_target::geometry)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.res_can_sell(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = p_user
      AND (p.resident_trust_tier IN ('trusted', 'verified') OR p.is_verified = true)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.res_care_check_in(p_care_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_carer uuid; v_subject uuid;
begin
  select carer_id, subject_id into v_carer, v_subject from res_care_circle where id = p_care_id;
  if v_subject is null then raise exception 'care circle not found'; end if;
  if auth.uid() not in (v_carer, v_subject) then raise exception 'not in this care circle'; end if;

  update res_care_circle set last_ok_at = now(), status = 'active' where id = p_care_id;
  perform res_notify(v_carer, 'res_care_missed', 'Check-in received', 'They are OK.',
                     jsonb_build_object('care_id', p_care_id));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_care_overdue()
 RETURNS TABLE(id uuid, subject_id uuid, carer_id uuid, missed_by interval)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.subject_id, c.carer_id,
         now() - (c.last_ok_at + case c.cadence when 'daily' then interval '1 day'
                                                 else interval '7 days' end)
    from res_care_circle c
   where c.status = 'active'
     and (c.subject_id = auth.uid() or c.carer_id = auth.uid())
     and now() > c.last_ok_at + case c.cadence when 'daily' then interval '1 day'
                                                else interval '7 days' end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_check_broadcast_priority()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_verified boolean;
begin
  if new.priority in ('urgent', 'critical') then
    select verified into v_verified from res_org_units where id = new.unit_id;
    if not coalesce(v_verified, false) then
      raise exception 'unit_not_verified: only a verified organisation can send at % priority', new.priority;
    end if;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_check_broadcast_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  select count(*) into v_count
  from res_org_broadcasts
  where unit_id = new.unit_id
    and created_at > now() - interval '1 hour';
  if v_count >= 5 then
    raise exception 'rate_limited: too many broadcasts from this unit in the last hour';
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_check_rate_limit(p_action text, p_max integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_window timestamptz;
  v_count integer;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into res_rate_limits (user_id, action, window_start, count)
  values (auth.uid(), p_action, v_window, 1)
  on conflict (user_id, action, window_start)
  do update set count = res_rate_limits.count + 1
  returning count into v_count;

  if v_count > p_max then
    raise exception 'rate_limit_exceeded: % (max % per % seconds)', p_action, p_max, p_window_seconds;
  end if;
  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_check_security_log_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  if new.user_id is not null then
    select count(*) into v_count
    from res_security_logs
    where user_id = new.user_id
      and created_at > now() - interval '1 minute';
    if v_count >= 60 then
      raise exception 'rate_limited: too many security log entries for this user';
    end if;
  else
    select count(*) into v_count
    from res_security_logs
    where user_id is null
      and created_at > now() - interval '1 minute';
    if v_count >= 300 then
      raise exception 'rate_limited: too many anonymous security log entries';
    end if;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_check_status_duration()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.source = 'crowd' and new.ends_at is not null
     and new.ends_at < new.starts_at + interval '8 hours' then
    raise exception 'crowd reports must cover at least an 8 hour window';
  end if;
  if new.source = 'official' then
    if new.provider_id is null then
      raise exception 'official reports must reference a provider';
    end if;
    if not exists (
      select 1 from res_infra_partner_admins
       where provider_id = new.provider_id and user_id = auth.uid()
    ) then
      raise exception 'not an admin for this provider';
    end if;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_chore_fairness(p_listing uuid)
 RETURNS TABLE(user_id uuid, completed integer, assigned integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.roommate_id,
         count(*) filter (where c.status = 'completed')::integer,
         count(*)::integer
    from res_chore_schedule c
   where c.listing_id = p_listing
     and c.created_at > now() - interval '28 days'
     and public.res_is_household_member(p_listing, auth.uid())
   group by c.roommate_id;
$function$
;

CREATE OR REPLACE FUNCTION public.res_claim_voucher(p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_landlord uuid;
begin
  update res_utility_tokens
     set status = 'claimed', claimed_by = auth.uid(), claimed_at = now()
   where id = p_token and status = 'available'
  returning landlord_id into v_landlord;

  if v_landlord is null then raise exception 'voucher_unavailable'; end if;

  perform res_notify(v_landlord, 'res_token_claim', 'Your voucher was claimed',
                     'Arrange the handover with them directly.',
                     jsonb_build_object('token_id', p_token));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_clear_home_area()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  delete from public.res_home_areas where user_id = auth.uid();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_client_error_summary(p_hours integer DEFAULT 24)
 RETURNS TABLE(label text, occurrences bigint, affected_users bigint, last_seen timestamp with time zone, sample_message text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    e.label,
    count(*) as occurrences,
    count(distinct e.user_id) as affected_users,
    max(e.created_at) as last_seen,
    (array_agg(e.message order by e.created_at desc))[1] as sample_message
  from res_client_errors e
  where e.created_at > now() - make_interval(hours => greatest(1, least(p_hours, 720)))
  group by e.label
  order by count(*) desc;
$function$
;

CREATE OR REPLACE FUNCTION public.res_client_error_summary_for_admin(p_hours integer DEFAULT 24)
 RETURNS TABLE(label text, occurrences bigint, affected_users bigint, last_seen timestamp with time zone, sample_message text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.res_is_platform_admin() then
    raise exception 'not_a_platform_admin';
  end if;

  return query
  select
    e.label,
    count(*) as occurrences,
    count(distinct e.user_id) as affected_users,
    max(e.created_at) as last_seen,
    (array_agg(e.message order by e.created_at desc))[1] as sample_message
  from res_client_errors e
  where e.created_at > now() - make_interval(hours => greatest(1, least(p_hours, 720)))
  group by e.label
  order by count(*) desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_coarsen_coord(p_value double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select round(p_value::numeric, 2)::double precision;
$function$
;

CREATE OR REPLACE FUNCTION public.res_comment_gossip(p_post uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform res_check_rate_limit('comment_gossip', 60, 3600);
  insert into res_gossip_comments (post_id, author_id, body)
  values (p_post, auth.uid(), p_body) returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_comment_service_report(p_report uuid, p_body text)
 RETURNS res_service_report_updates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_report res_service_reports;
  v_row res_service_report_updates;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if coalesce(trim(p_body), '') = '' then raise exception 'empty_comment'; end if;

  select * into v_report from res_service_reports where id = p_report;
  if not found then raise exception 'report_not_found'; end if;
  if not (v_report.reporter_id = auth.uid()
          or public.res_is_provider_admin(v_report.provider_id)
          or public.res_shares_locality(v_report.suburb, v_report.city)) then
    raise exception 'not_your_area';
  end if;

  perform public.res_check_rate_limit('service_comment', 20, 3600);

  insert into res_service_report_updates (report_id, author_id, kind, body)
  values (p_report, auth.uid(), 'comment', trim(p_body))
  returning * into v_row;

  if public.res_is_provider_admin(v_report.provider_id) and v_report.first_response_at is null then
    update res_service_reports set first_response_at = now() where id = p_report;
  end if;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_communities_near(p_lat double precision, p_lng double precision, p_radius_m double precision DEFAULT 15000)
 RETURNS TABLE(id uuid, name text, kind text, is_private boolean, lat double precision, lon double precision, radius_m numeric, member_count integer, distance_m double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.kind, c.is_private, c.lat, c.lon, c.radius_m,
         (select count(*)::int from res_community_members m where m.community_id = c.id) as member_count,
         res_distance_m(c.lat, c.lon, p_lat, p_lng) as distance_m
  from res_communities c
  where c.lat is not null and c.lon is not null
    and res_distance_m(c.lat, c.lon, p_lat, p_lng) <= greatest(100, least(80000, coalesce(p_radius_m, 15000)))
  order by distance_m
  limit 200;
$function$
;

CREATE OR REPLACE FUNCTION public.res_complete_chore(p_chore uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_chore record;
begin
  select * into v_chore from res_chore_schedule where id = p_chore;
  if v_chore is null then raise exception 'chore not found'; end if;
  if v_chore.roommate_id <> auth.uid() then raise exception 'not your chore'; end if;
  if v_chore.status = 'completed' then return; end if;  -- #18.3 idempotent, no XP farming

  update res_chore_schedule
     set status = 'completed', completed_at = now()
   where id = p_chore;

  perform res_bump_reputation(auth.uid(), 10, 'chore_completed');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_complete_dispatch(p_dispatch uuid, p_proof_url text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_disp record; v_owner uuid;
begin
  select d.*, s.owner_id into v_disp
    from res_service_dispatches d join res_handyman_services s on s.id = d.service_id
   where d.id = p_dispatch;
  if v_disp is null then raise exception 'dispatch not found'; end if;

  select owner_id into v_owner from res_handyman_services where id = v_disp.service_id;
  if v_owner <> auth.uid() then raise exception 'not_your_service'; end if;

  -- #42.3 completing requires proof of work
  if p_proof_url is null or length(p_proof_url) = 0 then
    raise exception 'proof_required';
  end if;

  update res_service_dispatches
     set status = 'completed', proof_file_url = p_proof_url
   where id = p_dispatch;

  perform res_notify(v_disp.sender_id, 'res_dispatch', 'Job marked complete',
                     'You can now review this business.',
                     jsonb_build_object('dispatch_id', p_dispatch, 'service_id', v_disp.service_id));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_confirm_service_report(p_report uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_report res_service_reports;
  v_count integer;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  select * into v_report from res_service_reports where id = p_report;
  if not found then raise exception 'report_not_found'; end if;
  if v_report.reporter_id = auth.uid() then
    raise exception 'own_report: you filed this one — it already counts';
  end if;
  if not (public.res_is_provider_admin(v_report.provider_id)
          or public.res_shares_locality(v_report.suburb, v_report.city)) then
    raise exception 'not_your_area';
  end if;

  perform public.res_check_rate_limit('service_confirm', 30, 3600);

  insert into res_service_report_confirmations (report_id, user_id)
  values (p_report, auth.uid())
  on conflict (report_id, user_id) do nothing;

  select count(*) into v_count from res_service_report_confirmations where report_id = p_report;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_confirm_tool_return(p_tool uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tool record;
begin
  select * into v_tool from res_tool_library where id = p_tool;
  if v_tool is null then raise exception 'tool not found'; end if;
  if v_tool.owner_id <> auth.uid() then raise exception 'not_your_tool'; end if;

  update res_tool_library
     set status = 'available', rented_by = null, rented_until = null
   where id = p_tool;

  -- On-time returns earn reputation; late ones don't
  if v_tool.rented_by is not null
     and (v_tool.rented_until is null or v_tool.rented_until >= current_date) then
    perform res_bump_reputation(v_tool.rented_by, 10, 'tool_returned_on_time');
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_confirm_trust_connection(p_requester uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  update res_trust_connections set status = 'confirmed', confirmed_at = now()
   where requester_id = p_requester and connection_id = auth.uid();
  if not found then raise exception 'no pending request from that user'; end if;
  insert into res_trust_connections (requester_id, connection_id, status, confirmed_at)
  values (auth.uid(), p_requester, 'confirmed', now())
  on conflict (requester_id, connection_id) do update set status = 'confirmed', confirmed_at = now();
  perform res_notify(p_requester, 'res_trust_confirmed', 'Trust connection confirmed',
    'Your next-of-kin trust connection was confirmed.', jsonb_build_object('connection_id', auth.uid()));
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_create_community(p_name text, p_kind text, p_suburb text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_radius_m numeric DEFAULT NULL::numeric, p_private boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform res_check_rate_limit('create_community', 3, 86400);

  insert into res_communities (name, kind, suburb, city, lat, lon, radius_m, is_private, created_by)
  values (p_name, p_kind, p_suburb, p_city, p_lat, p_lon, p_radius_m, p_private, auth.uid())
  returning id into v_id;

  insert into res_community_members (community_id, user_id, role)
  values (v_id, auth.uid(), 'founder');

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_create_invite(p_community uuid, p_max_uses integer DEFAULT 1, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_code text;
begin
  perform public.res_check_rate_limit('create_invite', 20, 86400);
  if not exists (
    select 1 from res_community_members
     where community_id = p_community and user_id = auth.uid() and role in ('admin','founder')
  ) then
    raise exception 'admin_required';
  end if;

  v_code := upper(substr(encode(extensions.gen_random_bytes(6), 'hex'), 1, 8));
  insert into res_community_invites (community_id, code, created_by, max_uses, expires_at)
  values (p_community, v_code, auth.uid(), p_max_uses, p_expires_at);
  return v_code;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_create_kin_verification_link(p_claimed_name text, p_relationship text)
 RETURNS res_kin_verification_links
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.res_kin_verification_links;
begin
  perform public.res_check_rate_limit('kin_link', 10, 86400);
  if auth.uid() is null then
    raise exception 'Must be signed in';
  end if;
  if trim(coalesce(p_claimed_name, '')) = '' then
    raise exception 'Name is required';
  end if;
  if trim(coalesce(p_relationship, '')) = '' then
    raise exception 'Relationship is required';
  end if;

  insert into public.res_kin_verification_links (requester_id, claimed_name, claimed_relationship)
    values (auth.uid(), trim(p_claimed_name), trim(p_relationship))
    returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_create_property(p_address text, p_suburb text, p_city text, p_lat double precision, p_lon double precision, p_total_rooms integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  perform public.res_check_rate_limit('create_property', 10, 86400);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into res_properties (landlord_id, address, suburb, city, lat, lon, total_rooms)
  values (auth.uid(), p_address, p_suburb, p_city, p_lat, p_lon, p_total_rooms)
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_create_room(p_property uuid, p_label text, p_price numeric, p_currency text, p_advantages text, p_disadvantages text, p_price_note text, p_photos text[])
 RETURNS res_rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_rooms;
begin
  perform public.res_check_rate_limit('create_room', 40, 86400);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if coalesce(trim(p_label), '') = '' then raise exception 'label_required'; end if;
  if not exists (select 1 from res_properties where id = p_property and landlord_id = auth.uid()) then
    raise exception 'not_your_property';
  end if;
  if coalesce(array_length(p_photos, 1), 0) > 6 then
    raise exception 'too_many_photos: 6 maximum per room';
  end if;

  insert into res_rooms (
    property_id, landlord_id, label, price, currency, advantages, disadvantages, price_note, photos
  ) values (
    p_property, auth.uid(), trim(p_label), p_price, coalesce(p_currency, 'ZAR'),
    nullif(trim(coalesce(p_advantages, '')), ''), nullif(trim(coalesce(p_disadvantages, '')), ''),
    nullif(trim(coalesce(p_price_note, '')), ''), coalesce(p_photos, '{}')
  )
  returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_default_target_hours(p_category text, p_severity text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case p_category
    when 'sewerage'   then case p_severity when 'critical' then 12 when 'high' then 24 when 'medium' then 48  else 72  end
    when 'water'      then case p_severity when 'critical' then 12 when 'high' then 24 when 'medium' then 48  else 72  end
    when 'power'      then case p_severity when 'critical' then 8  when 'high' then 24 when 'medium' then 48  else 72  end
    when 'network'    then case p_severity when 'critical' then 24 when 'high' then 48 when 'medium' then 72  else 120 end
    when 'fiber'      then case p_severity when 'critical' then 24 when 'high' then 48 when 'medium' then 72  else 120 end
    when 'road'       then case p_severity when 'critical' then 24 when 'high' then 72 when 'medium' then 168 else 336 end
    when 'waste'      then case p_severity when 'critical' then 24 when 'high' then 48 when 'medium' then 96  else 168 end
    when 'streetlight' then case p_severity when 'critical' then 48 when 'high' then 96 when 'medium' then 168 else 336 end
    else                    case p_severity when 'critical' then 24 when 'high' then 48 when 'medium' then 72  else 168 end
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_delete_property(p_property uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
begin
  perform public.res_check_rate_limit('delete_property', 10, 3600);
  select landlord_id into v_owner from public.res_properties where id = p_property;
  if v_owner is null then
    raise exception 'Property not found';
  end if;
  if v_owner <> auth.uid() then
    raise exception 'Not your property';
  end if;

  delete from public.res_room_occupants
    where room_id in (select id from public.res_rooms where property_id = p_property);

  delete from public.res_rooms where property_id = p_property;

  delete from public.res_listings where property_id = p_property;

  delete from public.res_properties where id = p_property;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_distance_m(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select 6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lon2 - lon1) / 2), 2)
  ));
$function$
;

CREATE OR REPLACE FUNCTION public.res_end_room_occupancy(p_occupant uuid)
 RETURNS res_room_occupants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_room_occupants;
  v_room uuid;
begin
  select room_id into v_room from res_room_occupants where id = p_occupant;
  if v_room is null then raise exception 'occupant_not_found'; end if;
  if not public.res_owns_room(v_room) then raise exception 'not_your_room'; end if;

  update res_room_occupants set moved_out_at = now()
  where id = p_occupant and moved_out_at is null
  returning * into v_row;

  if not exists (select 1 from res_room_occupants where room_id = v_room and moved_out_at is null) then
    update res_rooms set status = 'vacant' where id = v_room;
  end if;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_end_tenancy(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req record;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into v_req from res_room_requests where id = p_request;
  if v_req is null then raise exception 'request not found'; end if;
  if v_req.status <> 'approved' then raise exception 'this tenancy is not active'; end if;
  if auth.uid() not in (v_req.tenant_id, v_req.landlord_id) then
    raise exception 'not a party to this tenancy';
  end if;

  update res_room_requests set status = 'ended' where id = p_request;
  update res_listings set status = 'open' where id = v_req.listing_id and status = 'taken';

  perform res_notify(
    case when auth.uid() = v_req.tenant_id then v_req.landlord_id else v_req.tenant_id end,
    'res_tenancy_ended', 'Tenancy ended',
    'A tenancy you were part of has ended.',
    jsonb_build_object('listing_id', v_req.listing_id, 'request_id', p_request)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_ensure_area_probation(p_unit uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into res_org_unit_billing (unit_id, status, plan)
  select u.id, 'probation', public.res_area_plan_for_level(j.level)
  from res_org_units u
  join res_jurisdictions j on j.id = u.jurisdiction_id
  where u.id = p_unit and u.verified = true
  on conflict (unit_id) do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_exempt_unit_from_area_billing(p_unit uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'exemption_needs_a_reason';
  end if;
  insert into res_org_unit_billing (unit_id, status, exempt_reason, updated_at)
  values (p_unit, 'exempt', trim(p_reason), now())
  on conflict (unit_id) do update set
    status = 'exempt', exempt_reason = trim(p_reason), updated_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_expire_area_probations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  update res_org_unit_billing
     set status = 'lapsed', updated_at = now()
   where status = 'probation' and probation_ends_at <= now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_expire_market_items()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  with stale as (
    update res_market_items set status = 'gone'
     where status = 'available' and created_at < now() - interval '60 days'
    returning 1
  ) select count(*) into v_count from stale;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_expire_stale_alerts()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  with stale as (
    update res_alerts a
       set status = 'false_alarm', resolved_at = now()
     where a.status = 'active'
       and a.created_at < now() - interval '6 hours'
       and not exists (select 1 from res_alert_responders r where r.alert_id = a.id)
    returning 1
  ) select count(*) into v_count from stale;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_expire_stale_listings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  with stale as (
    update res_listings set status = 'paused'
     where status = 'open' and updated_at < now() - interval '37 days'
    returning 1
  ) select count(*) into v_count from stale;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_fanout_broadcast()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_unit_name text;
  v_audience integer;
begin
  if new.priority = 'normal' then
    return new;
  end if;

  select name into v_unit_name from res_org_units where id = new.unit_id;

  select count(*) into v_audience
  from res_resolve_broadcast_audience(new.unit_id)
  where follower_user_id <> new.sender_id;

  if v_audience > 20000 then
    raise exception 'audience_too_large: % recipients — contact support to send at this scale', v_audience;
  end if;

  insert into notifications (recipient_id, actor_id, type, title, body, message, data, action_url, read, is_read)
  select
    a.follower_user_id,
    new.sender_id,
    'res_org_broadcast',
    coalesce(v_unit_name, 'Announcement') || ': ' || new.title,
    new.body,
    new.body,
    jsonb_build_object(
      'priority', new.priority,
      'requires_ack', new.priority = 'critical',
      'broadcast_id', new.id,
      'unit_id', new.unit_id,
      'category', new.category
    ),
    '/dashboard/community?tab=notices&broadcast=' || new.id::text,
    false,
    false
  from res_resolve_broadcast_audience(new.unit_id) a
  where a.follower_user_id <> new.sender_id;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_flag_suspicious_listing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_median numeric; v_sample integer; v_recent integer;
begin
  select median, sample into v_median, v_sample
    from public.res_suburb_price_stats(new.suburb);

  if v_median is not null and v_sample >= 3 and new.price < v_median * 0.5 then
    new.flagged := true;
    new.flag_reason := 'Priced far below the suburb median — verify before paying anything.';
  end if;

  -- #22.2: a burst of listings from one landlord in an hour
  select count(*) into v_recent from res_listings
   where landlord_id = new.landlord_id and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    new.flagged := true;
    new.flag_reason := coalesce(new.flag_reason, 'Unusually many listings posted in a short window.');
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_get_kin_verification_link(p_token uuid)
 RETURNS TABLE(requester_name text, claimed_name text, claimed_relationship text, status text)
 LANGUAGE sql
