CREATE OR REPLACE FUNCTION public.res_is_unit_ancestor_or_self(p_ancestor uuid, p_unit uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive chain as (
    select id, parent_id from res_org_units where id = p_unit
    union all
    select u.id, u.parent_id from res_org_units u
    join chain c on u.id = c.parent_id
  )
  select exists (select 1 from chain where id = p_ancestor);
$function$
;

CREATE OR REPLACE FUNCTION public.res_join_community(p_community uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_private boolean;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select is_private into v_private from res_communities where id = p_community;
  if v_private is null then raise exception 'community not found'; end if;
  if v_private then raise exception 'invite_required: this community is private'; end if;

  insert into res_community_members (community_id, user_id, role)
  values (p_community, auth.uid(), 'member')
  on conflict (community_id, user_id) do nothing;  -- #11.1 double-join is a no-op
end;
$function$
;

