begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into res_lift_bookings (lift_id, rider_id, status)
  values (p_lift_id, auth.uid(), 'waitlisted')
  on conflict (lift_id, rider_id, trip_date) do update set status = 'waitlisted';
end;
