CREATE OR REPLACE FUNCTION public.res_listings_near(p_lat double precision, p_lng double precision, p_radius_m double precision DEFAULT 8000)
 RETURNS TABLE(id uuid, title text, price numeric, currency text, listing_type text, lat double precision, lon double precision, images text[], landlord_lives_here boolean, distance_m double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select l.id, l.title, l.price, l.currency, l.listing_type, l.lat, l.lon, l.images,
         l.landlord_lives_here,
         res_distance_m(l.lat, l.lon, p_lat, p_lng) as distance_m
  from res_listings l
  where l.lat is not null and l.lon is not null
    and coalesce(l.hidden, false) = false
    and coalesce(l.flagged, false) = false
    and l.status = 'open'
    and (l.visible_until is null or l.visible_until > now())
    and res_distance_m(l.lat, l.lon, p_lat, p_lng) <= greatest(100, least(50000, coalesce(p_radius_m, 8000)))
  order by distance_m
  limit 300;
$function$
;

CREATE OR REPLACE FUNCTION public.res_log_client_error(p_label text, p_message text DEFAULT NULL::text, p_context jsonb DEFAULT NULL::jsonb, p_path text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(trim(p_label), '') = '' then
    return;
  end if;

  begin
    perform public.res_check_rate_limit('client_error', 30, 3600);
  exception when others then
    -- Over the limit, or not signed in. Swallow: an error reporter that
    -- throws is worse than one that misses a report.
    return;
  end;

  insert into res_client_errors (user_id, label, message, context, path, app_version)
  values (
    auth.uid(),
    left(trim(p_label), 60),
    left(p_message, 2000),
    p_context,
    left(p_path, 300),
    left(p_app_version, 40)
  );
exception when others then
  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_maintenance_status(p_hours integer DEFAULT 48)
 RETURNS TABLE(task text, runs bigint, failures bigint, last_run timestamp with time zone, last_ok boolean, last_affected integer, last_error text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.task, count(*), count(*) filter (where not r.ok), max(r.ran_at),
         (array_agg(r.ok order by r.ran_at desc))[1],
         (array_agg(r.affected order by r.ran_at desc))[1],
         (array_agg(r.error order by r.ran_at desc))[1]
  from res_maintenance_runs r
  where r.ran_at > now() - make_interval(hours => greatest(1, least(p_hours, 720)))
  group by r.task
  order by count(*) filter (where not r.ok) desc, r.task;
$function$
;

