CREATE OR REPLACE FUNCTION public.res_match_saved_searches()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s record;
begin
  if new.hidden or new.status <> 'open' then return new; end if;

  for s in
    select * from res_saved_searches where notify = true and user_id <> new.landlord_id
  loop
    if (s.filters->>'suburb' is null or lower(s.filters->>'suburb') = lower(coalesce(new.suburb, '')))
       and (s.filters->>'maxPrice' is null or new.price <= (s.filters->>'maxPrice')::numeric)
       and (s.filters->>'wifi' is null or (s.filters->>'wifi')::boolean is not true or new.wifi)
       and (s.filters->>'parking' is null or (s.filters->>'parking')::boolean is not true or new.parking)
    then
      perform res_notify(s.user_id, 'res_room_request',
        'New room matches "' || s.name || '"',
        new.title,
        jsonb_build_object('listing_id', new.id, 'saved_search_id', s.id));
    end if;
  end loop;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_mirror_to_map()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid   uuid;
  v_lat   double precision;
  v_lon   double precision;
  v_sev   int;
  v_label text;
  v_note  text;
  v_resolved boolean;
  v_src   text := TG_TABLE_NAME;
  g       geometry;
BEGIN
  IF TG_TABLE_NAME = 'res_alerts' THEN
    IF NEW.kind NOT IN ('incident','suspicious') THEN RETURN NEW; END IF;
    v_uid := NEW.user_id; v_lat := NEW.lat; v_lon := NEW.lon;
    v_label := NEW.title; v_note := NEW.description;
    v_sev := CASE lower(coalesce(NEW.severity,''))
               WHEN 'low' THEN 1 WHEN 'medium' THEN 2
               WHEN 'high' THEN 3 WHEN 'critical' THEN 3
               ELSE 2 END;
    v_resolved := (lower(coalesce(NEW.status,'')) IN ('resolved','false_alarm','closed','cleared'))
                  OR NEW.resolved_at IS NOT NULL;
  ELSE
    v_uid := NEW.reporter_id; v_lat := NEW.lat; v_lon := NEW.lon;
    v_label := NEW.kind; v_note := NEW.detail; v_sev := 2;
    v_resolved := lower(coalesce(NEW.status,'')) IN
                  ('resolved','restored','cleared','normal','ok','back','online');
  END IF;

  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_uid) THEN
    RETURN NEW;
  END IF;
  IF v_lat IS NULL OR v_lon IS NULL
     OR v_lat < -90 OR v_lat > 90 OR v_lon < -180 OR v_lon > 180 THEN
    RETURN NEW;
  END IF;

  g := ST_SetSRID(ST_MakePoint(v_lon, v_lat), 4326);

  IF NOT v_resolved AND (
       SELECT count(*) FROM public.map_zones
       WHERE created_by = v_uid AND source_app = 'resident'
         AND status NOT IN ('removed','expired') AND ends_at > now()) >= 30 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.map_zones
    (ext_source, ext_id, source_app, event_id, kind, geom, label, note, severity,
     starts_at, ends_at, created_by, status)
  VALUES
    (v_src, NEW.id, 'resident', NULL, 'alert', g,
     NULLIF(btrim(left(v_label, 200)), ''),
     NULLIF(btrim(left(v_note,  500)), ''),
     v_sev,
     coalesce(NEW.created_at, now()),
     coalesce(NEW.created_at, now())
       + CASE WHEN v_resolved THEN interval '1 minute' ELSE interval '24 hours' END,
     v_uid,
     CASE WHEN v_resolved THEN 'expired' ELSE 'declared' END)
  ON CONFLICT (ext_source, ext_id) WHERE ext_source IS NOT NULL DO UPDATE SET
     geom     = EXCLUDED.geom,
     label    = EXCLUDED.label,
     note     = EXCLUDED.note,
     severity = EXCLUDED.severity,
     ends_at  = EXCLUDED.ends_at,
     status   = CASE WHEN EXCLUDED.status = 'expired' THEN 'expired'
                     WHEN public.map_zones.status = 'official' THEN 'official'
                     ELSE public.map_zones.status END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.res_moderate(p_community uuid, p_action text, p_subject_type text, p_subject_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  select role into v_role from res_community_members
   where community_id = p_community and user_id = auth.uid();

  -- coalesce is load-bearing. `v_role not in ('admin','founder')` is NULL
  -- when the caller is a member of nothing, and `if NULL then raise` does
  -- NOT fire — so the guard fell through and any signed-in user could
  -- moderate any community. Proven by exploit, not inferred.
  if coalesce(v_role, '') not in ('admin', 'founder') then
    raise exception 'admin_required';
  end if;

  if p_action in ('hide','unhide') then
    if p_subject_type = 'listing' then
      -- res_listings has no community_id, so a community admin cannot be
      -- scoped to their own community here. Restricted to the listing's own
      -- landlord acting, or a platform admin — previously ANY community
      -- admin could hide ANY listing on the platform.
      if not public.res_is_platform_admin()
         and not exists (select 1 from res_listings where id = p_subject_id and landlord_id = auth.uid()) then
        raise exception 'not_your_listing: listings are not community-scoped';
      end if;
      update res_listings set hidden = (p_action = 'hide') where id = p_subject_id;

    elsif p_subject_type = 'market_item' then
      update res_market_items set hidden = (p_action = 'hide')
       where id = p_subject_id and community_id = p_community;

    elsif p_subject_type = 'notice' then
      -- Same as listings: no community_id on res_notice_events.
      if not public.res_is_platform_admin()
         and not exists (select 1 from res_notice_events where id = p_subject_id and posted_by_id = auth.uid()) then
        raise exception 'not_your_notice: notices are not community-scoped';
      end if;
      update res_notice_events set hidden = (p_action = 'hide') where id = p_subject_id;

    elsif p_subject_type = 'gossip_post' then
      update res_gossip_posts set hidden = (p_action = 'hide')
       where id = p_subject_id and community_id = p_community;
    end if;

  elsif p_action = 'remove_member' then
    delete from res_community_members where community_id = p_community and user_id = p_subject_id;
  elsif p_action = 'promote' then
    update res_community_members set role = 'admin'
     where community_id = p_community and user_id = p_subject_id;
  elsif p_action = 'demote' then
    if v_role <> 'founder' then raise exception 'founder_required'; end if;
    update res_community_members set role = 'member'
     where community_id = p_community and user_id = p_subject_id and role <> 'founder';
  end if;

  insert into res_moderation_actions (community_id, actor_id, action, subject_type, subject_id, reason)
  values (p_community, auth.uid(), p_action, p_subject_type, p_subject_id, p_reason);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_my_area_notices()
 RETURNS TABLE(id uuid, unit_name text, target_label text, priority text, category text, title text, body text, sent_at timestamp with time zone, acknowledged_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select b.id, u.name, b.target_label, b.priority, b.category, b.title, b.body,
         b.sent_at, r.acknowledged_at
  from notifications n
  join res_area_broadcasts b on b.id = (n.data ->> 'area_broadcast_id')::uuid
  join res_org_units u on u.id = b.unit_id
  left join res_area_broadcast_receipts r
    on r.broadcast_id = b.id and r.user_id = auth.uid()
  where n.recipient_id = auth.uid()
    and n.type = 'res_area_broadcast'
  order by b.sent_at desc
  limit 100;
$function$
;

CREATE OR REPLACE FUNCTION public.res_my_jurisdictions()
 RETURNS TABLE(id uuid, name text, level text, external_ref text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select j.id, j.name, j.level, j.external_ref
  from res_home_areas h
  join res_jurisdictions j
    on ST_Covers(j.boundary, ST_MakePoint(h.lon, h.lat)::geography)
  where h.user_id = auth.uid()
  order by
    case j.level
      when 'ward' then 1 when 'service_area' then 2 when 'municipality' then 3
      when 'district' then 4 when 'province' then 5 else 6
    end,
    j.name;
$function$
;

CREATE OR REPLACE FUNCTION public.res_my_unit_verification(p_unit uuid)
 RETURNS TABLE(status text, decision_note text, decided_at timestamp with time zone, requested_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.status, r.decision_note, r.decided_at, r.created_at
  from res_unit_verification_requests r
  where r.unit_id = p_unit
    and public.res_user_is_sender_of_or_above(p_unit, auth.uid())
  order by r.created_at desc limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.res_notify(p_recipient uuid, p_type text, p_title text, p_body text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_muted text[];
  v_qs integer;
  v_qe integer;
  v_hour integer;
  v_blocked boolean;
begin
  if p_recipient is null or p_recipient = auth.uid() then
    return; -- never notify yourself
  end if;

  -- #23: a block silences notifications in both directions
  select exists (
    select 1 from res_blocks
    where (blocker_id = p_recipient and blocked_id = auth.uid())
       or (blocker_id = auth.uid() and blocked_id = p_recipient)
  ) into v_blocked;
  if v_blocked then return; end if;

  if p_type <> 'res_alert_panic' then
    select muted_types, quiet_hours_start, quiet_hours_end
      into v_muted, v_qs, v_qe
      from res_notification_prefs where user_id = p_recipient;

    if v_muted is not null and p_type = any(v_muted) then
      return;
    end if;

    if v_qs is not null and v_qe is not null then
      v_hour := extract(hour from now());
      if (v_qs < v_qe and v_hour >= v_qs and v_hour < v_qe)
         or (v_qs > v_qe and (v_hour >= v_qs or v_hour < v_qe)) then
        return;
      end if;
    end if;
  end if;

  insert into notifications (recipient_id, actor_id, type, title, body, message, data)
  values (p_recipient, auth.uid(), p_type, p_title, p_body, p_body, coalesce(p_data, '{}'::jsonb));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_notify_group_buy_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p record;
begin
  if new.status = 'completed' and old.status <> 'completed' then
    for p in select user_id from res_group_buy_pledges where group_buy_id = new.id loop
      perform res_notify(p.user_id, 'res_groupbuy_pledge',
        'Group buy reached its target', new.title,
        jsonb_build_object('group_buy_id', new.id));
    end loop;
  end if;
  return new;
end;
$function$
;

