 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid; v_name text;
begin
  select owner_id, business_name into v_owner, v_name
    from res_handyman_services where id = new.service_id;
  perform res_notify(v_owner, 'res_dispatch', 'New job request', coalesce(v_name, ''),
    jsonb_build_object('dispatch_id', new.id, 'service_id', new.service_id));
