CREATE OR REPLACE FUNCTION public.res_pending_reports(p_limit integer DEFAULT 100)
 RETURNS TABLE(subject_type text, subject_id uuid, report_count integer, reasons text[], first_reported_at timestamp with time zone, last_reported_at timestamp with time zone, details text[], currently_hidden boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.res_is_platform_admin() then
    raise exception 'admin_required';
  end if;

  return query
  select r.subject_type,
         r.subject_id,
         count(distinct r.reporter_id)::integer,
         array_agg(distinct r.reason),
         min(r.created_at),
         max(r.created_at),
         -- Reporter identities are deliberately NOT returned. A reviewer needs
         -- to know what was said and how many people said it, not who, and
         -- exposing complainants to whoever holds the admin role invites
         -- retaliation.
         array_remove(array_agg(distinct r.detail), null),
         coalesce(
           case r.subject_type
             when 'listing'     then (select l.hidden from res_listings l where l.id = r.subject_id)
             when 'market_item' then (select m.hidden from res_market_items m where m.id = r.subject_id)
             when 'notice'      then (select ne.hidden from res_notice_events ne where ne.id = r.subject_id)
             when 'gossip_post' then (select g.hidden from res_gossip_posts g where g.id = r.subject_id)
           end, false)
  from res_reports r
  where r.status = 'open'
  group by r.subject_type, r.subject_id
  order by count(distinct r.reporter_id) desc, min(r.created_at) asc
  limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_pending_urgent_broadcasts()
 RETURNS TABLE(id uuid, unit_id uuid, unit_name text, title text, body text, priority text, created_at timestamp with time zone, source text, target_label text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- The union is wrapped: Postgres will not take an expression in ORDER BY
  -- directly after a UNION, and this ordering is the whole point of merging
  -- the two sources in SQL rather than in the client.
  select q.id, q.unit_id, q.unit_name, q.title, q.body, q.priority,
         q.created_at, q.source, q.target_label
  from (
    select b.id, b.unit_id, u.name as unit_name, b.title, b.body, b.priority,
           b.created_at, 'follow'::text as source, null::text as target_label
    from res_org_broadcasts b
    join res_org_units u on u.id = b.unit_id
    left join res_org_broadcast_receipts r
           on r.broadcast_id = b.id and r.user_id = auth.uid()
    where b.priority in ('urgent', 'critical')
      and r.acknowledged_at is null
      and (b.expires_at is null or b.expires_at > now())
      and exists (
        select 1 from res_org_follows f
        where f.follower_user_id = auth.uid()
          and public.res_is_unit_ancestor_or_self(b.unit_id, f.unit_id)
      )

    union all

    -- Membership comes from the notification actually delivered, so the banner
    -- can never show something the rest of the app has no record of them
    -- receiving.
    select ab.id, ab.unit_id, u.name as unit_name, ab.title, ab.body, ab.priority,
           ab.sent_at as created_at, 'area'::text as source, ab.target_label
    from res_area_broadcasts ab
    join res_org_units u on u.id = ab.unit_id
    left join res_area_broadcast_receipts ar
           on ar.broadcast_id = ab.id and ar.user_id = auth.uid()
    where ab.priority in ('urgent', 'critical')
      and ar.acknowledged_at is null
      and (ab.expires_at is null or ab.expires_at > now())
      and exists (
        select 1 from notifications n
        where n.recipient_id = auth.uid()
          and n.type = 'res_area_broadcast'
          and (n.data ->> 'area_broadcast_id')::uuid = ab.id
      )
  ) q
  -- Worst first across BOTH sources: the banner shows one notice at a time, so
  -- this decides whether an evacuation or a school notice is what a resident
  -- actually sees.
  order by
    case q.priority when 'critical' then 0 else 1 end,
    q.created_at desc
  limit 20;
$function$
;

CREATE OR REPLACE FUNCTION public.res_pending_verification_requests()
 RETURNS TABLE(request_id uuid, unit_id uuid, unit_name text, unit_tier text, official_title text, evidence_url text, contact_email text, note text, requested_jurisdiction_id uuid, requested_jurisdiction_name text, requested_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select r.id, r.unit_id, u.name, u.tier, r.official_title, r.evidence_url,
         r.contact_email, r.note, r.requested_jurisdiction_id, j.name, r.created_at
  from res_unit_verification_requests r
  join res_org_units u on u.id = r.unit_id
  left join res_jurisdictions j on j.id = r.requested_jurisdiction_id
  where r.status = 'pending' and public.res_is_platform_admin()
  order by r.created_at;
$function$
;

CREATE OR REPLACE FUNCTION public.res_platform_health()
 RETURNS TABLE(component text, status text, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subs int; v_vault int; v_jurisdictions int;
  v_last_maint timestamptz; v_maint_failures int; v_errors int;
begin
  if not public.res_is_platform_admin() then
    raise exception 'not_a_platform_admin';
  end if;

  select count(*) into v_subs from web_push_subscriptions;
  begin
    select count(*) into v_vault from vault.decrypted_secrets where name = 'service_role_key';
  exception when others then v_vault := 0;
  end;

  if v_vault = 0 and v_subs > 0 then
    return query select 'Push notifications'::text, 'broken'::text,
      v_subs || ' people have granted notification permission, but the dispatcher has no service_role_key in the vault — nothing has ever been delivered to any of them. Set it in Supabase → Vault. See docs/PUSH-SETUP.md.';
  elsif v_vault = 0 then
    return query select 'Push notifications'::text, 'idle'::text,
      'Not configured, and nobody has subscribed yet — so nothing is being missed.'::text;
  elsif v_subs = 0 then
    return query select 'Push notifications'::text, 'idle'::text,
      'Configured, but nobody has granted permission yet.'::text;
  else
    return query select 'Push notifications'::text, 'ok'::text,
      v_subs || ' subscribed devices, dispatcher configured.';
  end if;

  select count(*) into v_jurisdictions from res_jurisdictions;
  if v_jurisdictions = 0 then
    return query select 'Area boundaries'::text, 'broken'::text,
      'No jurisdictions loaded — no official can be bound to an area, so area broadcasts cannot reach anyone. Run theresident_import_boundaries.sql.';
  else
    return query select 'Area boundaries'::text, 'ok'::text, v_jurisdictions || ' areas loaded.';
  end if;

  select max(ran_at) into v_last_maint from res_maintenance_runs;
  select count(*) into v_maint_failures from res_maintenance_runs
   where ran_at > now() - interval '7 days' and not ok;

  if v_last_maint is null then
    return query select 'Scheduled maintenance'::text, 'broken'::text,
      'Has never run. Listings will not expire, tools never return, logs grow without bound.'::text;
  elsif v_last_maint < now() - interval '48 hours' then
    return query select 'Scheduled maintenance'::text, 'broken'::text,
      'Last ran ' || to_char(v_last_maint, 'YYYY-MM-DD HH24:MI') || ' — the daily job has stopped.';
  elsif v_maint_failures > 0 then
    return query select 'Scheduled maintenance'::text, 'degraded'::text,
      v_maint_failures || ' task failure(s) in the last 7 days.';
  else
    return query select 'Scheduled maintenance'::text, 'ok'::text,
      'Last ran ' || to_char(v_last_maint, 'YYYY-MM-DD HH24:MI') || '.';
  end if;

  select count(*) into v_errors from res_client_errors where created_at > now() - interval '24 hours';
  if v_errors = 0 then
    return query select 'Crash reports'::text, 'ok'::text, 'No crashes reported in the last 24 hours.'::text;
  else
    return query select 'Crash reports'::text, 'degraded'::text,
      v_errors || ' crash(es) in the last 24 hours — see the list below.';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_pledge_group_buy(p_group_buy_id uuid, p_quantity integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total integer;
  v_target integer;
  v_deadline timestamptz;
  v_status text;
begin
  perform public.res_check_rate_limit('group_buy_pledge', 30, 86400);
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'quantity must be positive';
  end if;

  select target_quantity, deadline, status
    into v_target, v_deadline, v_status
    from res_group_buys
   where id = p_group_buy_id
     for update;

  if not found then
    raise exception 'group buy not found';
  end if;
  if v_status <> 'open' then
    raise exception 'group buy is not open';
  end if;
  if v_deadline < now() then
    raise exception 'group buy deadline has passed';
  end if;

  insert into res_group_buy_pledges (group_buy_id, user_id, quantity)
  values (p_group_buy_id, auth.uid(), p_quantity)
  on conflict (group_buy_id, user_id)
  do update set quantity = excluded.quantity;

  select coalesce(sum(quantity), 0) into v_total
    from res_group_buy_pledges
   where group_buy_id = p_group_buy_id;

  update res_group_buys
     set current_quantity = v_total,
         status = case when v_total >= v_target then 'completed' else status end
   where id = p_group_buy_id;

  return v_total;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_post_gossip(p_community uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform res_check_rate_limit('post_gossip', 30, 3600);
  insert into res_gossip_posts (author_id, community_id, body)
  values (auth.uid(), p_community, p_body) returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_preview_area_audience(p_unit uuid, p_target geography, p_priority text DEFAULT 'important'::text, p_category text DEFAULT NULL::text, p_suburbs text[] DEFAULT NULL::text[], p_cities text[] DEFAULT NULL::text[])
 RETURNS TABLE(pinned_count integer, text_matched_count integer, total_count integer, block_reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reason text;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  if not public.res_user_is_sender_of_or_above(p_unit, auth.uid()) then
    raise exception 'not_a_sender_for_this_unit';
  end if;

  v_reason := public.res_area_broadcast_block_reason(p_unit, p_target);
  if v_reason is not null then
    return query select 0, 0, 0, v_reason;
    return;
  end if;

  return query
  select
    count(*) filter (where a.matched_by = 'home_area')::integer,
    count(*) filter (where a.matched_by = 'suburb_text')::integer,
    count(*)::integer,
    null::text
  from public.res_resolve_area_audience(p_target, p_priority, p_category, p_suburbs, p_cities) a;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_property_occupancy(p_property uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'total_rooms', p.total_rooms,
    'occupied_rooms', (select count(*) from res_listings l where l.property_id = p.id and l.status = 'taken'),
    'listed_rooms', (select count(*) from res_listings l where l.property_id = p.id)
  )
  from res_properties p
  where p.id = p_property
    and p.landlord_id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.res_provider_performance(p_provider uuid DEFAULT NULL::uuid)
 RETURNS TABLE(provider_id uuid, provider_name text, open_count integer, resolved_count integer, median_ack_hours numeric, median_resolve_hours numeric, oldest_open_days numeric, overdue_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    p.id,
    p.name,
    count(*) filter (where r.status in ('submitted','acknowledged','in_progress'))::integer,
    count(*) filter (where r.status in ('resolved','closed'))::integer,
    round((percentile_cont(0.5) within group (
      order by extract(epoch from (r.acknowledged_at - r.created_at)) / 3600.0
    ) filter (where r.acknowledged_at is not null))::numeric, 1),
    round((percentile_cont(0.5) within group (
      order by extract(epoch from (r.resolved_at - r.created_at)) / 3600.0
    ) filter (where r.resolved_at is not null))::numeric, 1),
    round((max(extract(epoch from (now() - r.created_at)) / 86400.0)
      filter (where r.status in ('submitted','acknowledged','in_progress')))::numeric, 1),
    count(*) filter (
      where r.status in ('submitted','acknowledged','in_progress')
        and now() > r.created_at + make_interval(hours => r.target_hours)
    )::integer
  from res_infra_providers p
  join res_service_reports r on r.provider_id = p.id
  where p_provider is null or p.id = p_provider
  group by p.id, p.name
  order by p.name;
$function$
;

CREATE OR REPLACE FUNCTION public.res_prune_client_errors()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  delete from res_client_errors where created_at < now() - interval '90 days';
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_prune_maintenance_runs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  delete from res_maintenance_runs where ran_at < now() - interval '90 days';
  get diagnostics v_count = row_count;
  return v_count;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_prune_security_logs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer;
begin
  delete from res_security_logs where created_at < now() - interval '180 days';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_public_profile(p_user_id uuid)
 RETURNS TABLE(id uuid, username text, display_name text, avatar_url text, bio text, city text, suburb text, is_verified boolean, vibe_score integer, social_integrity_score integer, badges text[], xp integer, member_since timestamp with time zone, role text, gossip_post_count integer, is_self boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not signed in';
  end if;
  if p_user_id is null then
    raise exception 'no resident given';
  end if;

  -- Blocks in EITHER direction hide the profile.
  if exists (
    select 1 from res_blocks b
     where (b.blocker_id = v_me and b.blocked_id = p_user_id)
        or (b.blocker_id = p_user_id and b.blocked_id = v_me)
  ) then
    raise exception 'resident_unavailable';
  end if;

  return query
  select
    pr.id,
    pr.username,
    pr.display_name,
    pr.avatar_url,
    pr.bio,
    coalesce(rp.city, pr.city)                                   as city,
    rp.suburb,
    coalesce(pr.is_verified, false)                              as is_verified,
    pr.vibe_score,
    pr.social_integrity_score,
    pr.badges,
    pr.xp,
    pr.created_at                                                as member_since,
    rp.role,
    (select count(*)::integer from res_gossip_posts g
      where g.author_id = pr.id and coalesce(g.hidden, false) = false)
                                                                 as gossip_post_count,
    (pr.id = v_me)                                               as is_self
  from profiles pr
  left join res_profiles rp on rp.id = pr.id
  where pr.id = p_user_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_public_profile_posts(p_user_id uuid, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, body text, created_at timestamp with time zone, media_url text, media_type text, background_style text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not signed in';
  end if;
  if exists (
    select 1 from res_blocks b
     where (b.blocker_id = v_me and b.blocked_id = p_user_id)
        or (b.blocker_id = p_user_id and b.blocked_id = v_me)
  ) then
    raise exception 'resident_unavailable';
  end if;

  return query
  select g.id, g.body, g.created_at, g.media_url, g.media_type, g.background_style
    from res_gossip_posts g
   where g.author_id = p_user_id
     and coalesce(g.hidden, false) = false
   order by g.created_at desc
   limit greatest(1, least(coalesce(p_limit, 20), 50));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_public_provider_tier(p_user uuid)
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select tier from res_subscriptions
   where user_id = p_user and product = 'provider' and status = 'active'
   limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.res_push_area_broadcast(p_broadcast uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_row res_area_broadcasts;
  v_unit_name text;
  v_recipients uuid[];
  v_key text;
  v_url text;
begin
  select * into v_row from res_area_broadcasts where id = p_broadcast;
  if v_row.id is null then return 0; end if;
  if v_row.priority not in ('urgent', 'critical') then return 0; end if;

  select name into v_unit_name from res_org_units where id = v_row.unit_id;

  -- The audience is read back from the notifications already written, not
  -- re-resolved. Re-resolving could reach someone who was not notified, which
  -- would mean a push with nothing behind it in the app.
  select array_agg(n.recipient_id) into v_recipients
  from notifications n
  where n.type = 'res_area_broadcast'
    and (n.data ->> 'area_broadcast_id')::uuid = p_broadcast;

  if v_recipients is null or array_length(v_recipients, 1) is null then return 0; end if;

  begin
    select decrypted_secret into v_key
    from vault.decrypted_secrets where name = 'service_role_key';
  exception when others then
    return 0;
  end;
  if v_key is null then return 0; end if;

  v_url := 'https://feevvddvrjmfbhffccbf.supabase.co';

  perform net.http_post(
    url := v_url || '/functions/v1/web-push-send',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object(
      'userIds', to_jsonb(v_recipients),
      'title', coalesce(v_unit_name, 'Notice') || ': ' || v_row.title,
      'body', v_row.body,
      'url', '/dashboard/community?tab=notices&area=' || v_row.id::text,
      'tag', 'area-' || v_row.id::text,
      'requireInteraction', v_row.priority = 'critical'
    )
  );

  return array_length(v_recipients, 1);
exception when others then
  -- Deliberate catch-all: a push failure must never undo a broadcast that has
  -- already been delivered in-app.
  return 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_radius_target(p_lat double precision, p_lon double precision, p_metres double precision)
 RETURNS geography
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select ST_Buffer(ST_MakePoint(p_lon, p_lat)::geography, least(greatest(p_metres, 50), 50000));
$function$
;

CREATE OR REPLACE FUNCTION public.res_raise_alert(p_kind text, p_title text, p_description text, p_lat double precision, p_lon double precision, p_severity text DEFAULT 'medium'::text, p_community uuid DEFAULT NULL::uuid, p_suburb text DEFAULT NULL::text, p_city text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing uuid;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  -- #1.4 cooldown: a second press within 5 minutes updates the live alert
  -- rather than creating another (pocket-trigger protection).
  select id into v_existing
    from res_alerts
   where user_id = auth.uid() and kind = p_kind and status = 'active'
     and created_at > now() - interval '5 minutes'
   order by created_at desc limit 1;

  if v_existing is not null then
    update res_alerts
       set title = p_title, description = p_description,
           lat = coalesce(p_lat, lat), lon = coalesce(p_lon, lon),
           severity = p_severity
     where id = v_existing;
    return v_existing;
  end if;

  perform res_check_rate_limit('raise_alert', 3, 3600);

  insert into res_alerts (user_id, kind, title, description, lat, lon, community_id, suburb, city, severity)
  values (auth.uid(), p_kind, p_title, p_description, p_lat, p_lon, p_community, p_suburb, p_city, p_severity)
  returning id into v_id;

  -- #1.2 fan-out to verified neighbours
  perform public.res_broadcast_alert(v_id);
  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_redeem_invite(p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_inv record;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  select * into v_inv from res_community_invites
   where code = upper(p_code) for update;

  if v_inv is null then raise exception 'invalid_code'; end if;
  if v_inv.revoked then raise exception 'code_revoked'; end if;
  if v_inv.expires_at is not null and v_inv.expires_at < now() then raise exception 'code_expired'; end if;
  if v_inv.uses >= v_inv.max_uses then raise exception 'code_used_up'; end if;

  insert into res_community_members (community_id, user_id, role)
  values (v_inv.community_id, auth.uid(), 'member')
  on conflict (community_id, user_id) do nothing;

  update res_community_invites set uses = uses + 1 where id = v_inv.id;
  return v_inv.community_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_reject_request(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req record;
begin
  select * into v_req from res_room_requests where id = p_request;
  if v_req.landlord_id <> auth.uid() then raise exception 'not your listing'; end if;
  update res_room_requests set status = 'rejected' where id = p_request;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_reject_unit_verification(p_unit uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if not public.res_is_platform_admin() then raise exception 'not_a_platform_admin'; end if;
  if coalesce(trim(p_note), '') = '' then raise exception 'rejection_needs_a_reason'; end if;
  update res_unit_verification_requests
     set status = 'rejected', decided_by = v_uid, decided_at = now(), decision_note = trim(p_note)
   where unit_id = p_unit and status = 'pending';
  insert into res_org_unit_audit (unit_id, action, actor_id, detail)
  values (p_unit, 'rejected', v_uid, trim(p_note));
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_release_seat(p_lift_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_seats integer;
begin
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  update res_lift_clubs
     set available_seats = available_seats + 1
   where id = p_lift_id
     and available_seats < total_seats
  returning available_seats into v_seats;

  if v_seats is null then
    raise exception 'seat cannot be released';
  end if;

  return v_seats;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_release_stale_claims()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer;
begin
  with released as (
    update res_utility_tokens
       set status = 'available', claimed_by = null, claimed_at = null
     where status = 'claimed' and claimed_at < now() - interval '24 hours'
    returning 1
  ) select count(*) into v_count from released;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_report_content(p_subject_type text, p_subject_id uuid, p_reason text, p_detail text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reports integer;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform res_check_rate_limit('report_content', 20, 3600);

  insert into res_reports (reporter_id, subject_type, subject_id, reason, detail)
  values (auth.uid(), p_subject_type, p_subject_id, p_reason, p_detail)
  on conflict (reporter_id, subject_type, subject_id) do nothing;

  select count(distinct reporter_id) into v_reports
    from res_reports where subject_type = p_subject_type and subject_id = p_subject_id and status = 'open';

  if v_reports >= 3 then
    if p_subject_type = 'listing' then
      update res_listings set hidden = true where id = p_subject_id;
    elsif p_subject_type = 'market_item' then
      update res_market_items set hidden = true where id = p_subject_id;
    elsif p_subject_type = 'notice' then
      update res_notice_events set hidden = true where id = p_subject_id;
    end if;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_report_infra_official(p_provider uuid, p_kind text, p_status text, p_detail text, p_suburb text, p_city text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  perform public.res_check_rate_limit('infra_report', 10, 3600);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not exists (select 1 from res_infra_partner_admins where provider_id = p_provider and user_id = auth.uid()) then
    raise exception 'not an admin for this provider';
  end if;
  insert into res_neighbourhood_status
    (reporter_id, kind, status, detail, suburb, city, source, provider_id, starts_at, ends_at)
  values
    (auth.uid(), p_kind, p_status, p_detail, p_suburb, p_city, 'official', p_provider, p_starts_at, p_ends_at)
  returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_report_map_zone(p_kind text, p_lat double precision, p_lon double precision, p_label text, p_note text, p_severity integer, p_duration_hours integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_recent int;
begin
  perform public.res_check_rate_limit('map_report', 20, 3600);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_kind not in ('road_closed','heavy_traffic','detour','no_parking') then
    raise exception 'invalid_kind: residents can only report road_closed, heavy_traffic, detour, or no_parking';
  end if;
  if p_duration_hours < 1 or p_duration_hours > 24*14 then
    raise exception 'invalid_duration: must be between 1 hour and 14 days';
  end if;
  if p_lat is null or p_lon is null or p_lat < -90 or p_lat > 90 or p_lon < -180 or p_lon > 180 then
    raise exception 'invalid_coordinates';
  end if;

  -- Basic spam guard: no more than 5 zone reports per person per hour.
  select count(*) into v_recent from map_zones
   where created_by = auth.uid() and source_app = 'resident' and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    raise exception 'rate_limited: too many reports in the last hour';
  end if;

  insert into map_zones (source_app, kind, geom, label, note, severity, starts_at, ends_at, created_by, status)
  values (
    'resident', p_kind,
    ST_SetSRID(ST_MakePoint(p_lon, p_lat), 4326),
    nullif(btrim(left(coalesce(p_label,''), 200)), ''),
    nullif(btrim(left(coalesce(p_note,''), 500)), ''),
    greatest(1, least(3, coalesce(p_severity, 2))),
    now(), now() + (p_duration_hours || ' hours')::interval,
    auth.uid(), 'declared'
  ) returning id into v_id;

  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_report_road_segment(p_kind text, p_lat1 double precision, p_lon1 double precision, p_lat2 double precision, p_lon2 double precision, p_label text, p_note text, p_severity integer, p_starts_at timestamp with time zone, p_duration_hours integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_recent int; v_start timestamptz;
begin
  perform public.res_check_rate_limit('road_report', 20, 3600);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_kind not in ('road_closed','detour') then
    raise exception 'invalid_kind: segment reports are for road_closed or detour only';
  end if;
  if p_duration_hours < 1 or p_duration_hours > 24*14 then
    raise exception 'invalid_duration: must be between 1 hour and 14 days';
  end if;
  if p_lat1 is null or p_lon1 is null or p_lat2 is null or p_lon2 is null
     or p_lat1 < -90 or p_lat1 > 90 or p_lat2 < -90 or p_lat2 > 90
     or p_lon1 < -180 or p_lon1 > 180 or p_lon2 < -180 or p_lon2 > 180 then
    raise exception 'invalid_coordinates';
  end if;

  v_start := coalesce(p_starts_at, now());
  if v_start < now() - interval '1 hour' then
    raise exception 'invalid_start: cannot be in the past';
  end if;
  if v_start > now() + interval '14 days' then
    raise exception 'invalid_start: too far in the future';
  end if;

  select count(*) into v_recent from map_zones
   where created_by = auth.uid() and source_app = 'resident' and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    raise exception 'rate_limited: too many reports in the last hour';
  end if;

  insert into map_zones (source_app, kind, geom, label, note, severity, starts_at, ends_at, created_by, status)
  values (
    'resident', p_kind,
    ST_SetSRID(ST_MakeLine(ST_MakePoint(p_lon1, p_lat1), ST_MakePoint(p_lon2, p_lat2)), 4326),
    nullif(btrim(left(coalesce(p_label,''), 200)), ''),
    nullif(btrim(left(coalesce(p_note,''), 500)), ''),
    greatest(1, least(3, coalesce(p_severity, 2))),
    v_start, v_start + (p_duration_hours || ' hours')::interval,
    auth.uid(), 'declared'
  ) returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_report_status(p_kind text, p_status text, p_suburb text, p_detail text DEFAULT NULL::text, p_community uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_before boolean;
  v_after boolean;
  v_recipient uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  perform res_check_rate_limit('report_status', 10, 3600);

  select confirmed into v_before from res_status_consensus(p_kind, p_suburb);

  insert into res_neighbourhood_status (reporter_id, kind, status, detail, community_id, suburb, lat, lon, ends_at)
  values (auth.uid(), p_kind, p_status, p_detail, p_community, p_suburb, p_lat, p_lon, p_ends_at)
  returning id into v_id;

  select confirmed into v_after from res_status_consensus(p_kind, p_suburb);

  if coalesce(v_after, false) and not coalesce(v_before, false) then
    for v_recipient in
      select distinct m.user_id from res_community_members m
       where p_community is not null and m.community_id = p_community and m.user_id <> auth.uid()
    loop
      perform res_notify(v_recipient, 'res_status',
        upper(p_kind) || ' outage confirmed in ' || p_suburb,
        coalesce(p_detail, 'Multiple neighbours are reporting this.'),
        jsonb_build_object('kind', p_kind, 'suburb', p_suburb, 'status', p_status));
    end loop;
  end if;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_request_move_assist(p_service_id uuid, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_gate jsonb; v_id uuid; v_category text;
begin
  perform public.res_check_rate_limit('move_assist', 10, 86400);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select category into v_category from res_handyman_services where id = p_service_id;
  if v_category is null then raise exception 'service not found'; end if;
  if v_category not in ('Bakkie / Transport','Moving Assistant') then
    raise exception 'not a move-assist service';
  end if;
  v_gate := res_trust_gate(auth.uid());
  if not (v_gate->>'unlocked')::boolean then
    raise exception 'trust_gate_locked: build your next-of-kin trust circle first';
  end if;
  insert into res_service_dispatches (service_id, sender_id, message, status)
  values (p_service_id, auth.uid(), p_message, 'pending') returning id into v_id;
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_request_tool_return(p_tool uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid; v_title text;
begin
  update res_tool_library set status = 'pending_return'
   where id = p_tool and rented_by = auth.uid() and status = 'rented'
  returning owner_id, title into v_owner, v_title;

  if v_owner is null then raise exception 'not_your_rental'; end if;

  perform res_notify(v_owner, 'res_dispatch', 'Tool returned — please confirm', v_title,
                     jsonb_build_object('tool_id', p_tool));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_request_trust_connection(p_connection uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.res_check_rate_limit('trust_request', 20, 86400);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_connection = auth.uid() then raise exception 'cannot connect to yourself'; end if;
  insert into res_trust_connections (requester_id, connection_id) values (auth.uid(), p_connection)
  on conflict (requester_id, connection_id) do nothing;
  perform res_notify(p_connection, 'res_trust_request', 'Trust circle request',
    'Someone wants to add you as a next-of-kin trust contact.',
    jsonb_build_object('requester_id', auth.uid()));
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_request_unit_verification(p_unit uuid, p_official_title text DEFAULT NULL::text, p_evidence_url text DEFAULT NULL::text, p_contact_email text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_jurisdiction uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid(); v_id uuid;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if not public.res_user_is_sender_of_or_above(p_unit, v_uid) then
    raise exception 'not_a_sender_for_this_unit';
  end if;
  if exists (select 1 from res_org_units where id = p_unit and verified = true) then
    raise exception 'already_verified';
  end if;
  perform public.res_check_rate_limit('verification_request', 5, 86400);
  insert into res_unit_verification_requests (
    unit_id, requested_by, official_title, evidence_url, contact_email, note, requested_jurisdiction_id
  ) values (
    p_unit, v_uid, nullif(trim(p_official_title), ''), nullif(trim(p_evidence_url), ''),
    nullif(trim(p_contact_email), ''), nullif(trim(p_note), ''), p_jurisdiction
  )
  on conflict (unit_id) where status = 'pending'
  do update set official_title = excluded.official_title, evidence_url = excluded.evidence_url,
    contact_email = excluded.contact_email, note = excluded.note,
    requested_jurisdiction_id = excluded.requested_jurisdiction_id, created_at = now()
  returning id into v_id;
  insert into res_org_unit_audit (unit_id, action, actor_id, detail)
  values (p_unit, 'verification_requested', v_uid, nullif(trim(p_official_title), ''));
  return v_id;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_resolve_alert(p_alert_id uuid, p_false_alarm boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update res_alerts
     set status = case when p_false_alarm then 'false_alarm' else 'resolved' end,
         resolved_at = now()
   where id = p_alert_id and user_id = auth.uid();
  if not found then raise exception 'not your alert'; end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_resolve_area_audience(p_target geography, p_priority text DEFAULT 'important'::text, p_category text DEFAULT NULL::text, p_suburbs text[] DEFAULT NULL::text[], p_cities text[] DEFAULT NULL::text[])
 RETURNS TABLE(user_id uuid, matched_by text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with muted as (
    select np.user_id
    from res_notification_prefs np
    where p_priority is distinct from 'critical'
      and (
        np.muted_types @> array['res_area_broadcast']
        or (p_category is not null
            and np.muted_types @> array['res_area_broadcast:' || p_category])
      )
  ),
  pinned as (
    select h.user_id
    from res_home_areas h
    where p_target is not null
      and ST_Covers(p_target, ST_MakePoint(h.lon, h.lat)::geography)
  ),
  by_text as (
    select rp.id as user_id
    from res_profiles rp
    where not exists (select 1 from pinned p where p.user_id = rp.id)
      and (
        (p_suburbs is not null and rp.suburb is not null
           and lower(trim(rp.suburb)) = any (select lower(trim(s)) from unnest(p_suburbs) s))
        or (p_cities is not null and rp.city is not null
           and lower(trim(rp.city)) = any (select lower(trim(c)) from unnest(p_cities) c))
      )
  )
  select user_id, 'home_area' as matched_by from pinned
  where user_id not in (select user_id from muted)
  union all
  select user_id, 'suburb_text' as matched_by from by_text
  where user_id not in (select user_id from muted);
$function$
;

CREATE OR REPLACE FUNCTION public.res_resolve_broadcast_audience(p_unit uuid)
 RETURNS TABLE(follower_user_id uuid, email_opt_in boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recursive descendants as (
    select id from res_org_units where id = p_unit
    union all
    select u.id from res_org_units u join descendants d on u.parent_id = d.id
  )
  select f.follower_user_id, bool_or(f.email_opt_in) as email_opt_in
  from res_org_follows f
  where f.unit_id in (select id from descendants)
  group by f.follower_user_id;
$function$
;

CREATE OR REPLACE FUNCTION public.res_resolve_report(p_subject_type text, p_subject_id uuid, p_action text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_hide boolean;
begin
  if not public.res_is_platform_admin() then
    raise exception 'admin_required';
  end if;
  if coalesce(p_action, '') not in ('hide', 'restore', 'dismiss') then
    raise exception 'invalid_action';
  end if;

  -- coalesce, not a bare comparison: `NULL not in (...)` is NULL, and
  -- `if NULL then raise` does not fire. That exact shape was a live privilege
  -- escalation in res_moderate earlier in this project's history.

  if p_action in ('hide', 'restore') then
    v_hide := (p_action = 'hide');
    if p_subject_type = 'listing' then
      update res_listings set hidden = v_hide where id = p_subject_id;
    elsif p_subject_type = 'market_item' then
      update res_market_items set hidden = v_hide where id = p_subject_id;
    elsif p_subject_type = 'notice' then
      update res_notice_events set hidden = v_hide where id = p_subject_id;
    elsif p_subject_type = 'gossip_post' then
      -- Gossip posts were reportable but had no auto-hide branch at all, so
      -- reporting one did nothing whatsoever.
      update res_gossip_posts set hidden = v_hide where id = p_subject_id;
    else
      raise exception 'unknown_subject_type: %', p_subject_type;
    end if;
  end if;

  update res_reports
     set status = case when p_action = 'dismiss' then 'dismissed' else 'actioned' end
   where subject_type = p_subject_type
     and subject_id = p_subject_id
     and status = 'open';

  -- Permanent record of who decided what. community_id is null: this is a
  -- platform-level decision, not a community one.
  insert into res_moderation_actions (community_id, actor_id, action, subject_type, subject_id, reason)
  values (null, auth.uid(), 'report_' || p_action, p_subject_type, p_subject_id, p_note);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_respond_kin_verification_link(p_token uuid, p_confirmed boolean, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text;
begin
  select status into v_status from public.res_kin_verification_links where token = p_token;
  if v_status is null then
    raise exception 'Link not found';
  end if;
  if v_status <> 'pending' then
    raise exception 'This link has already been answered';
  end if;

  update public.res_kin_verification_links
    set status = case when p_confirmed then 'confirmed' else 'denied' end,
        responder_note = p_note,
        responded_at = now()
    where token = p_token;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_respond_to_alert(p_alert_id uuid, p_status text DEFAULT 'coming'::text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner uuid;
  v_verified boolean;
  v_title text;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  select is_verified into v_verified from profiles where id = auth.uid();
  if not coalesce(v_verified, false) then
    raise exception 'verification_required: only verified neighbours can respond to alerts';
  end if;

  select user_id, title into v_owner, v_title from res_alerts where id = p_alert_id;
  if v_owner is null then raise exception 'alert not found'; end if;

  insert into res_alert_responders (alert_id, responder_id, status, note)
  values (p_alert_id, auth.uid(), p_status, p_note)
  on conflict do nothing;

  update res_alert_responders
     set status = p_status, note = coalesce(p_note, note)
   where alert_id = p_alert_id and responder_id = auth.uid();

  -- #2.3 every transition tells the person who raised it
  perform res_notify(v_owner, 'res_alert_response',
    case p_status when 'arrived' then 'Help has arrived' else 'A neighbour is responding' end,
    v_title, jsonb_build_object('alert_id', p_alert_id, 'status', p_status));

  -- #2.5 first arrival marks the alert as having help on scene
  if p_status = 'arrived' then
    perform res_bump_reputation(auth.uid(), 25, 'alert_response');
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_reunite_lost_found(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner uuid;
begin
  update res_lost_found set status = 'reunited' where id = p_id and user_id = auth.uid()
  returning user_id into v_owner;
  if v_owner is null then raise exception 'not_your_post'; end if;
  perform res_bump_reputation(auth.uid(), 15, 'lost_found_reunited');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_revoke_unit_verification(p_unit uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if not public.res_is_platform_admin() then raise exception 'not_a_platform_admin'; end if;
  if coalesce(trim(p_note), '') = '' then raise exception 'revocation_needs_a_reason'; end if;
  update res_org_units set verified = false where id = p_unit;
  if not found then raise exception 'unknown_unit'; end if;
  insert into res_org_unit_audit (unit_id, action, actor_id, detail)
  values (p_unit, 'unverified', v_uid, trim(p_note));
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_room_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_rotate_chores(p_listing uuid, p_tasks text[], p_days text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_members uuid[];
  v_offset integer;
  i integer;
  v_count integer := 0;
begin
  if not public.res_is_household_member(p_listing, auth.uid()) then
    raise exception 'not_household_member';
  end if;

  select array_agg(user_id order by user_id) into v_members
    from public.res_household_members(p_listing);
  if v_members is null or array_length(v_members, 1) = 0 then
    raise exception 'no household members';
  end if;

  -- Rotate the starting member each week so the same person isn't always first
  v_offset := (extract(week from now())::integer) % array_length(v_members, 1);

  delete from res_chore_schedule where listing_id = p_listing;

  for i in 1 .. array_length(p_tasks, 1) loop
    insert into res_chore_schedule (listing_id, roommate_id, task_name, day_of_week, status)
    values (
      p_listing,
      v_members[((i - 1 + v_offset) % array_length(v_members, 1)) + 1],
      p_tasks[i],
      coalesce(p_days[i], 'Any'),
      'pending'
    );
    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_run_maintenance()
 RETURNS TABLE(task text, ok boolean, affected integer, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tasks constant text[] := array[
    'res_expire_stale_listings','res_expire_market_items','res_expire_stale_alerts',
    'res_auto_return_tools','res_release_stale_claims','res_expire_area_probations',
    'res_prune_security_logs','res_prune_client_errors'
  ];
  v_task text; v_affected integer; v_started timestamptz; v_error text;
begin
  foreach v_task in array v_tasks loop
    v_started := clock_timestamp(); v_affected := null; v_error := null;
    begin
      -- Each in its own block: a run that aborts halfway is a scheduler that
      -- silently stops doing the remaining jobs while still looking alive.
      execute format('select %I()', v_task) into v_affected;
    exception
      when undefined_function then v_error := 'not installed';
      when others then v_error := left(sqlerrm, 500);
    end;
    insert into res_maintenance_runs (task, ok, affected, error, duration_ms)
    values (v_task, v_error is null, v_affected, v_error,
            (extract(epoch from (clock_timestamp() - v_started)) * 1000)::integer);
    task := v_task; ok := v_error is null; affected := v_affected; error := v_error;
    return next;
  end loop;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_save_request(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req record;
begin
  select * into v_req from res_room_requests where id = p_request;
  if v_req is null then raise exception 'request not found'; end if;
  if v_req.landlord_id <> auth.uid() then raise exception 'not your listing'; end if;
  update res_room_requests set status = 'saved' where id = p_request;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_search_jurisdictions(p_query text, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, name text, level text, external_ref text, parent_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select j.id, j.name, j.level, j.external_ref, p.name
  from res_jurisdictions j
  left join res_jurisdictions p on p.id = j.parent_id
  where public.res_is_platform_admin()
    and (coalesce(trim(p_query), '') = '' or j.name ilike '%' || trim(p_query) || '%')
  order by
    case j.level when 'ward' then 1 when 'service_area' then 2 when 'municipality' then 3
                 when 'district' then 4 when 'province' then 5 else 6 end,
    j.name
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$function$
;

CREATE OR REPLACE FUNCTION public.res_send_area_broadcast(p_unit uuid, p_title text, p_body text, p_priority text DEFAULT 'important'::text, p_category text DEFAULT NULL::text, p_jurisdiction uuid DEFAULT NULL::uuid, p_lat double precision DEFAULT NULL::double precision, p_lon double precision DEFAULT NULL::double precision, p_metres double precision DEFAULT NULL::double precision, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS res_area_broadcasts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_target geography;
  v_kind text;
  v_label text;
  v_level text;
  v_reason text;
  v_unit_name text;
  v_verified boolean;
  v_places record;
  v_sent_today integer;
  v_cap integer;
  v_row public.res_area_broadcasts;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if coalesce(trim(p_title), '') = '' or coalesce(trim(p_body), '') = '' then
    raise exception 'empty_broadcast';
  end if;
  if not public.res_user_is_sender_of_or_above(p_unit, v_uid) then
    raise exception 'not_a_sender_for_this_unit';
  end if;

  select name, verified into v_unit_name, v_verified from res_org_units where id = p_unit;
  if not coalesce(v_verified, false) then
    raise exception 'not_verified';
  end if;

  if p_jurisdiction is not null then
    select boundary, name, level into v_target, v_label, v_level
    from res_jurisdictions where id = p_jurisdiction;
    if v_target is null then raise exception 'unknown_jurisdiction'; end if;
    v_kind := 'jurisdiction';
  elsif p_lat is not null and p_lon is not null then
    v_target := public.res_radius_target(p_lat, p_lon, coalesce(p_metres, 3000));
    v_kind := 'radius';
    v_label := 'Within ' || round(least(greatest(coalesce(p_metres, 3000), 50), 50000))::text || 'm of a point';
    select j.level into v_level
    from res_org_units u join res_jurisdictions j on j.id = u.jurisdiction_id
    where u.id = p_unit;
  else
    raise exception 'no_target';
  end if;

  v_reason := public.res_area_broadcast_block_reason(p_unit, v_target);
  if v_reason is not null then
    raise exception 'area_blocked: %', v_reason;
  end if;

  -- Billing (Phase F). A 'critical' notice is NEVER gated: an evacuation must
  -- send whether or not anyone paid. Everything below it needs a live licence
  -- — probation, active or exempt.
  if p_priority <> 'critical' then
    begin
      perform public.res_ensure_area_probation(p_unit);
      if not coalesce((select allows_routine from public.res_area_billing_state(p_unit)), false) then
        raise exception 'area_licence_required: this office has no active area-messaging licence';
      end if;
    exception
      when undefined_function then null;
    end;
  end if;

  perform public.res_check_rate_limit('area_broadcast', 5, 3600);

  v_cap := public.res_area_daily_cap(v_level);
  select count(*) into v_sent_today
  from res_area_broadcasts
  where unit_id = p_unit and sent_at > now() - interval '24 hours';
  if v_sent_today >= v_cap then
    raise exception 'daily_cap_reached: % per day at this level', v_cap;
  end if;

  select * into v_places from public.res_area_place_names(v_target);

  insert into res_area_broadcasts (
    unit_id, sender_id, target, target_kind, jurisdiction_id, target_label,
    radius_metres, priority, category, title, body, expires_at
  ) values (
    p_unit, v_uid, v_target, v_kind, p_jurisdiction, v_label,
    case when v_kind = 'radius' then least(greatest(coalesce(p_metres, 3000), 50), 50000) end,
    p_priority, p_category, trim(p_title), trim(p_body), p_expires_at
  ) returning * into v_row;

  create temp table if not exists _area_audience (user_id uuid, matched_by text) on commit drop;
  delete from _area_audience;
  insert into _area_audience
  select a.user_id, a.matched_by
  from public.res_resolve_area_audience(
    v_target, p_priority, p_category, v_places.suburbs, v_places.cities
  ) a
  where a.user_id <> v_uid;

  select count(*) filter (where matched_by = 'home_area'),
         count(*) filter (where matched_by = 'suburb_text'),
         count(*)
    into v_row.pinned_count, v_row.text_matched_count, v_row.recipient_count
  from _area_audience;

  if v_row.recipient_count > 20000 then
    raise exception 'audience_too_large: % recipients — contact support to send at this scale', v_row.recipient_count;
  end if;

  update res_area_broadcasts
     set pinned_count = v_row.pinned_count,
         text_matched_count = v_row.text_matched_count,
         recipient_count = v_row.recipient_count
   where id = v_row.id;

  if p_priority <> 'normal' then
    insert into notifications (recipient_id, actor_id, type, title, body, message, data, action_url, read, is_read, expires_at)
    select
      a.user_id, v_uid, 'res_area_broadcast',
      coalesce(v_unit_name, 'Notice') || ': ' || trim(p_title),
      trim(p_body), trim(p_body),
      jsonb_build_object(
        'priority', p_priority,
        'requires_ack', p_priority = 'critical',
        'area_broadcast_id', v_row.id,
        'unit_id', p_unit,
        'category', p_category,
        'target_label', v_label,
        'matched_by', a.matched_by
      ),
      '/dashboard/community?tab=notices&area=' || v_row.id::text,
      false, false, p_expires_at
    from _area_audience a;

    begin
      perform public.res_push_area_broadcast(v_row.id);
    exception when undefined_function then
      null;
    end;
  end if;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_service_report_set_reference()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.reference is null or new.reference = '' then
    new.reference := 'SR-' || to_char(now(), 'YYYY') || '-'
                  || lpad(nextval('res_service_report_ref_seq')::text, 5, '0');
  end if;
  return new;
end;
$function$
;

