 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_set_area_billing(p_unit uuid, p_status text, p_plan text DEFAULT NULL::text, p_customer_code text DEFAULT NULL::text, p_subscription_code text DEFAULT NULL::text, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into res_org_unit_billing (
    unit_id, status, plan, paystack_customer_code,
    paystack_subscription_code, current_period_end, updated_at
  ) values (
    p_unit, p_status, p_plan, p_customer_code,
    p_subscription_code, p_period_end, now()
  )
  on conflict (unit_id) do update set
    status = excluded.status,
    plan = coalesce(excluded.plan, res_org_unit_billing.plan),
    paystack_customer_code = coalesce(excluded.paystack_customer_code, res_org_unit_billing.paystack_customer_code),
    paystack_subscription_code = coalesce(excluded.paystack_subscription_code, res_org_unit_billing.paystack_subscription_code),
    current_period_end = coalesce(excluded.current_period_end, res_org_unit_billing.current_period_end),
    updated_at = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_set_home_area(p_lat double precision, p_lon double precision, p_granularity text DEFAULT 'coarse'::text, p_suburb text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS res_home_areas
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.res_home_areas;
  v_lat double precision;
  v_lon double precision;
  v_granularity text;
begin
  perform public.res_check_rate_limit('set_home_area', 20, 3600);
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;

  if p_lat is null or p_lon is null then
    raise exception 'coordinates_required';
  end if;
  if p_lat < -90 or p_lat > 90 or p_lon < -180 or p_lon > 180 then
    raise exception 'coordinates_out_of_range: lat must be -90..90 and lon -180..180';
  end if;

  v_granularity := coalesce(nullif(trim(p_granularity), ''), 'coarse');
  if v_granularity not in ('coarse', 'exact') then
    raise exception 'invalid_granularity';
  end if;

  if v_granularity = 'coarse' then
    v_lat := public.res_coarsen_coord(p_lat);
    v_lon := public.res_coarsen_coord(p_lon);
  else
    v_lat := p_lat;
    v_lon := p_lon;
  end if;

  insert into public.res_home_areas (user_id, lat, lon, granularity, suburb, city, label, set_at)
  values (
    auth.uid(), v_lat, v_lon, v_granularity,
    nullif(trim(coalesce(p_suburb, '')), ''),
    nullif(trim(coalesce(p_city, '')), ''),
    nullif(trim(coalesce(p_label, '')), ''),
    now()
  )
  on conflict (user_id) do update set
    lat = excluded.lat,
    lon = excluded.lon,
    granularity = excluded.granularity,
    suburb = excluded.suburb,
    city = excluded.city,
    label = excluded.label,
    set_at = now()
  returning * into v_row;

  if v_row.suburb is not null or v_row.city is not null then
    update public.res_profiles
       set suburb = coalesce(v_row.suburb, suburb),
           city   = coalesce(v_row.city, city)
     where id = auth.uid();
  end if;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_set_occupant_visibility(p_occupant uuid, p_visibility text)
 RETURNS res_room_occupants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_room_occupants;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_visibility not in ('landlord_only', 'shared_with_housemates') then
    raise exception 'invalid_visibility';
  end if;

  update res_room_occupants
     set visibility = p_visibility
   where id = p_occupant and tenant_id = auth.uid()
  returning * into v_row;

  if v_row.id is null then raise exception 'not_your_occupancy'; end if;
  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_set_service_report_status(p_report uuid, p_status text, p_note text)
 RETURNS res_service_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_report res_service_reports;
  v_is_provider boolean;
  v_is_reporter boolean;
  v_old_status text;
  v_now timestamptz := now();
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;

  select * into v_report from res_service_reports where id = p_report;
  if not found then raise exception 'report_not_found'; end if;
  v_old_status := v_report.status;

  v_is_provider := public.res_is_provider_admin(v_report.provider_id);
  v_is_reporter := v_report.reporter_id = auth.uid();

  if not v_is_provider and not (v_is_reporter and p_status in ('closed', 'submitted')) then
    raise exception 'not_your_report: only % can set that status',
      coalesce((select name from res_infra_providers where id = v_report.provider_id), 'the provider');
  end if;

  update res_service_reports
     set status = p_status,
         first_response_at = case
           when v_is_provider and first_response_at is null then v_now
           else first_response_at end,
         acknowledged_at = case
           when p_status = 'acknowledged' and acknowledged_at is null then v_now
           else acknowledged_at end,
         resolved_at = case
           when p_status = 'resolved' then v_now
           when p_status = 'submitted' then null
           else resolved_at end,
         closed_at = case
           when p_status = 'closed' then v_now
           when p_status = 'submitted' then null
           else closed_at end
   where id = p_report
   returning * into v_report;

  insert into res_service_report_updates (report_id, author_id, kind, body, from_status, to_status)
  values (p_report, auth.uid(), 'status_change', nullif(trim(coalesce(p_note, '')), ''),
          v_old_status, p_status);

  return v_report;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_shares_locality(p_suburb text, p_city text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from res_profiles rp
    where rp.id = auth.uid()
      and (
        (p_suburb is not null and rp.suburb is not null and lower(rp.suburb) = lower(p_suburb))
        or (p_city is not null and rp.city is not null and lower(rp.city) = lower(p_city))
      )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.res_start_area_probation_on_verify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.verified = true and new.jurisdiction_id is not null then
    perform public.res_ensure_area_probation(new.id);
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_status_consensus(p_kind text, p_suburb text)
 RETURNS TABLE(confirmed boolean, reports integer, latest_status text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with recent as (
    select status, reporter_id, created_at
      from res_neighbourhood_status
     where kind = p_kind and suburb = p_suburb
       and created_at > now() - interval '30 minutes'
  )
  select
    (select count(distinct reporter_id) from recent where status in ('down','stage')) >= 3,
    (select count(distinct reporter_id)::integer from recent where status in ('down','stage')),
    (select status from recent order by created_at desc limit 1);
$function$
;

CREATE OR REPLACE FUNCTION public.res_submit_property_verification(p_property uuid, p_doc_url text, p_geocode_mismatch boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  update res_properties
     set verification_doc_url = p_doc_url,
         address_geocode_mismatch = coalesce(p_geocode_mismatch, false),
         doc_review_status = 'pending',
         updated_at = now()
   where id = p_property and landlord_id = auth.uid();
  if not found then raise exception 'property not found or not yours'; end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_submit_review(p_subject_type text, p_subject_id uuid, p_rating integer, p_body text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_eligible boolean := false;
begin
  perform public.res_check_rate_limit('review', 10, 3600);
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_subject_type = 'user' and p_subject_id = auth.uid() then raise exception 'cannot review yourself'; end if;

  if p_subject_type = 'service' then
    select exists (
      select 1 from res_service_dispatches d
       where d.service_id = p_subject_id and d.sender_id = auth.uid() and d.status = 'completed'
    ) into v_eligible;
  elsif p_subject_type = 'tool' then
    select exists (
      select 1 from res_tool_library t
       where t.id = p_subject_id and t.rented_by = auth.uid()
    ) into v_eligible;
  elsif p_subject_type = 'listing' then
    select exists (
      select 1 from res_room_requests r
       where r.listing_id = p_subject_id and r.tenant_id = auth.uid() and r.status = 'approved'
    ) into v_eligible;
  elsif p_subject_type = 'skill' then
    v_eligible := true;
  elsif p_subject_type = 'user' then
    select exists (
      select 1 from res_room_requests r
       where r.status = 'approved' and (
         (r.tenant_id = auth.uid() and r.landlord_id = p_subject_id) or
         (r.landlord_id = auth.uid() and r.tenant_id = p_subject_id)
       )
    ) into v_eligible;
  end if;

  if not v_eligible then
    raise exception 'not_eligible: you can only review something you have used';
  end if;

  insert into res_reviews (subject_type, subject_id, author_id, rating, body)
  values (p_subject_type, p_subject_id, auth.uid(), p_rating, p_body)
  on conflict (subject_type, subject_id, author_id)
  do update set rating = excluded.rating, body = excluded.body, updated_at = now();

  if p_subject_type = 'service' then
    update res_handyman_services s
       set rating = coalesce((select avg(rating) from res_reviews
                               where subject_type = 'service' and subject_id = s.id), 5.0),
           reviews_count = (select count(*) from res_reviews
                             where subject_type = 'service' and subject_id = s.id)
     where s.id = p_subject_id;
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_submit_service_report(p_category text, p_title text, p_detail text, p_severity text, p_suburb text, p_city text, p_provider uuid, p_provider_name_raw text, p_lat double precision, p_lon double precision)
 RETURNS res_service_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_service_reports;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if coalesce(trim(p_title), '') = '' then
    raise exception 'title_required: describe the problem in a few words';
  end if;
  if coalesce(trim(p_suburb), '') = '' or coalesce(trim(p_city), '') = '' then
    raise exception 'locality_required: we need the suburb and city so your neighbours can confirm it';
  end if;

  perform public.res_check_rate_limit('service_report', 5, 3600);

  insert into res_service_reports (
    reporter_id, provider_id, provider_name_raw, category, title, detail,
    severity, suburb, city, lat, lon, target_hours
  ) values (
    auth.uid(), p_provider, nullif(trim(coalesce(p_provider_name_raw, '')), ''),
    p_category, trim(p_title), nullif(trim(coalesce(p_detail, '')), ''),
    coalesce(p_severity, 'medium'), trim(p_suburb), trim(p_city), p_lat, p_lon,
    public.res_default_target_hours(p_category, coalesce(p_severity, 'medium'))
  )
  returning * into v_row;

  insert into res_service_report_updates (report_id, author_id, kind, body, to_status)
  values (v_row.id, auth.uid(), 'system', 'Report filed.', 'submitted');

  update res_profiles
     set suburb = coalesce(nullif(trim(suburb), ''), trim(p_suburb)),
         city   = coalesce(nullif(trim(city), ''), trim(p_city))
   where id = auth.uid();

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_suburb_price_stats(p_suburb text)
 RETURNS TABLE(median numeric, low numeric, high numeric, sample integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    percentile_cont(0.5) within group (order by price)::numeric,
    percentile_cont(0.25) within group (order by price)::numeric,
    percentile_cont(0.75) within group (order by price)::numeric,
    count(*)::integer
  from res_listings
  where suburb = p_suburb and status = 'open' and not hidden
  having count(*) >= 3;
$function$
;

CREATE OR REPLACE FUNCTION public.res_suggest_communities(p_lat double precision, p_lon double precision)
 RETURNS TABLE(id uuid, name text, kind text, distance_m double precision)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select c.id, c.name, c.kind, res_distance_m(p_lat, p_lon, c.lat, c.lon)
    from res_communities c
   where c.lat is not null and c.lon is not null
     and not c.is_private
     and res_distance_m(p_lat, p_lon, c.lat, c.lon) <= coalesce(c.radius_m, 1000)
   order by array_position(array['street','block','complex','estate','suburb'], c.kind),
            res_distance_m(p_lat, p_lon, c.lat, c.lon);
$function$
;

CREATE OR REPLACE FUNCTION public.res_sync_trust(p_user uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user UUID := COALESCE(p_user, auth.uid());
  v_rp RECORD;
  v_trusted BOOLEAN := false;
  v_verified BOOLEAN := false;
  v_tier TEXT;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF;
  -- auth.uid() is NULL for internal callers (cron, service_role), which are
  -- allowed to sync anyone. A browser session always has one, and may only
  -- ever sync itself.
  IF auth.uid() IS NOT NULL AND v_user <> auth.uid() THEN
    RAISE EXCEPTION 'may only sync own trust';
  END IF;
  IF to_regclass('public.res_profiles') IS NULL THEN RETURN NULL; END IF;

  SELECT * INTO v_rp FROM public.res_profiles WHERE id = v_user;
  IF FOUND THEN
    v_trusted := v_rp.role IS NOT NULL
             AND COALESCE(length(trim(v_rp.bio)), 0) >= 20
             AND v_rp.gender IS NOT NULL;
    v_verified := v_trusted
              AND COALESCE(v_rp.verification_doc_url, '') <> ''
              AND v_rp.verification_status = 'reviewed';
  END IF;

  v_tier := CASE WHEN v_verified THEN 'verified' WHEN v_trusted THEN 'trusted' ELSE NULL END;

  UPDATE public.profiles SET
    resident_trust_tier = v_tier,
    is_verified = CASE WHEN v_verified THEN true ELSE is_verified END,
    social_integrity_score = GREATEST(
      COALESCE(social_integrity_score, 50),
      CASE WHEN v_verified THEN 75 WHEN v_trusted THEN 62 ELSE 0 END
    )
  WHERE id = v_user;

  RETURN v_tier;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.res_targetable_jurisdictions(p_unit uuid)
 RETURNS TABLE(id uuid, name text, level text, is_own boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select j.id, j.name, j.level, (j.id = own.id) as is_own
  from res_org_units u
  join res_jurisdictions own on own.id = u.jurisdiction_id
  join res_jurisdictions j
    on j.id = own.id
    or ST_Covers(own.boundary::geometry, j.boundary::geometry)
  where u.id = p_unit
    and u.verified = true
    and public.res_user_is_sender_of_or_above(p_unit, auth.uid())
  order by (j.id = own.id) desc,
    case j.level
      when 'national' then 1 when 'province' then 2 when 'district' then 3
      when 'municipality' then 4 when 'ward' then 5 else 6
    end,
    j.name;
$function$
;

CREATE OR REPLACE FUNCTION public.res_toggle_echo(p_notice_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare joined boolean;
begin
  perform public.res_check_rate_limit('toggle', 300, 3600);
  if auth.uid() is null then
    raise exception 'not signed in';
  end if;
  update res_notice_events
     set echos = case when auth.uid() = any(echos)
                      then array_remove(echos, auth.uid())
                      else array_append(echos, auth.uid()) end
   where id = p_notice_id
  returning auth.uid() = any(echos) into joined;
  return coalesce(joined, false);
end;
$function$
;

