CREATE OR REPLACE FUNCTION public.res_trust_gate(p_user uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := coalesce(p_user, auth.uid());
  v_direct int;
  v_qualified int;
  v_unlocked boolean;
  v_status text;
begin
  if v_user is null then raise exception 'not signed in'; end if;
  if auth.uid() is not null and v_user <> auth.uid() then
    raise exception 'may only read own trust standing';
  end if;

  select count(distinct other) into v_direct from (
    select case when requester_id = v_user then connection_id else requester_id end as other
    from res_trust_connections
    where status = 'confirmed' and (requester_id = v_user or connection_id = v_user)
  ) t;

  select count(*) into v_qualified from (
    select case when requester_id = v_user then connection_id else requester_id end as other
    from res_trust_connections
    where status = 'confirmed' and (requester_id = v_user or connection_id = v_user)
  ) direct
  where (
    select count(distinct other2) from (
      select case when requester_id = direct.other then connection_id else requester_id end as other2
      from res_trust_connections
      where status = 'confirmed' and (requester_id = direct.other or connection_id = direct.other)
    ) t2
  ) >= 5;

  v_unlocked := v_direct >= 5 and v_qualified >= 3;
  v_status := case
    when v_unlocked then 'established'
    when v_direct >= 3 then 'building'
    else 'new'
  end;

  return jsonb_build_object('status', v_status, 'unlocked', v_unlocked);
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_update_room(p_room uuid, p_label text, p_price numeric, p_currency text, p_advantages text, p_disadvantages text, p_price_note text, p_photos text[])
 RETURNS res_rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row res_rooms;
begin
  if not public.res_owns_room(p_room) then raise exception 'not_your_room'; end if;
  if coalesce(array_length(p_photos, 1), 0) > 6 then
    raise exception 'too_many_photos: 6 maximum per room';
  end if;

  update res_rooms set
    label = coalesce(nullif(trim(p_label), ''), label),
    price = coalesce(p_price, price),
    currency = coalesce(p_currency, currency),
    advantages = nullif(trim(coalesce(p_advantages, '')), ''),
    disadvantages = nullif(trim(coalesce(p_disadvantages, '')), ''),
    price_note = nullif(trim(coalesce(p_price_note, '')), ''),
    photos = coalesce(p_photos, photos)
  where id = p_room
  returning * into v_row;

  return v_row;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_upsert_jurisdiction(p_name text, p_level text, p_external_ref text, p_geojson text, p_parent_ref text DEFAULT NULL::text, p_parent_level text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_parent uuid;
  v_geom geometry;
begin
  if coalesce(trim(p_name), '') = '' then
    raise exception 'name_required';
  end if;

  v_geom := ST_SetSRID(ST_GeomFromGeoJSON(p_geojson), 4326);
  if v_geom is null then
    raise exception 'invalid_geojson';
  end if;
  v_geom := ST_Multi(v_geom);
  if ST_IsEmpty(v_geom) then
    raise exception 'empty_boundary';
  end if;

  if p_parent_ref is not null and p_parent_level is not null then
    select id into v_parent from res_jurisdictions
      where level = p_parent_level and external_ref = p_parent_ref;
  end if;

  insert into res_jurisdictions (name, level, external_ref, parent_id, boundary)
  values (trim(p_name), p_level, nullif(trim(coalesce(p_external_ref, '')), ''),
          v_parent, v_geom::geography)
  on conflict (level, external_ref) where external_ref is not null
  do update set
    name = excluded.name,
    parent_id = coalesce(excluded.parent_id, res_jurisdictions.parent_id),
    boundary = excluded.boundary,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.res_user_is_sender_of_or_above(p_target_unit uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from res_org_memberships m
    where m.user_id = p_user
      and m.role = 'sender'
      and public.res_is_unit_ancestor_or_self(m.unit_id, p_target_unit)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.res_waitlist_request(p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_req record;
begin
  perform public.res_check_rate_limit('waitlist', 20, 86400);
  select * into v_req from res_room_requests where id = p_request;
  if v_req is null then raise exception 'request not found'; end if;
  if v_req.landlord_id <> auth.uid() then raise exception 'not your listing'; end if;
  update res_room_requests set status = 'waitlisted' where id = p_request;
  perform res_notify(v_req.tenant_id, 'res_request_waitlisted', 'Added to the waitlist',
    'The landlord put your application on the waitlist.',
    jsonb_build_object('listing_id', v_req.listing_id, 'request_id', p_request));
end; $function$
;

CREATE OR REPLACE FUNCTION public.res_withdraw_unit_verification(p_unit uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not public.res_user_is_sender_of_or_above(p_unit, auth.uid()) then
    raise exception 'not_a_sender_for_this_unit';
  end if;
  update res_unit_verification_requests
     set status = 'withdrawn', decided_at = now(), decided_by = auth.uid()
   where unit_id = p_unit and status = 'pending';
end; $function$
;

CREATE OR REPLACE FUNCTION public.zone_verify(p_zone uuid, p_vote text)
 RETURNS map_zones
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); c int; d int; z public.map_zones;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'not signed in'; END IF;
  IF p_vote NOT IN ('confirm','dispute') THEN RAISE EXCEPTION 'invalid vote'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.map_zones WHERE id = p_zone AND status NOT IN ('removed','expired')) THEN
    RAISE EXCEPTION 'zone not found';
  END IF;
  INSERT INTO public.map_zone_votes (zone_id, user_id, vote)
  VALUES (p_zone, uid, p_vote)
  ON CONFLICT (zone_id, user_id) DO UPDATE SET vote = EXCLUDED.vote, created_at = now();
  SELECT count(*) FILTER (WHERE vote='confirm'), count(*) FILTER (WHERE vote='dispute')
    INTO c, d FROM public.map_zone_votes WHERE zone_id = p_zone;
  UPDATE public.map_zones
     SET confirm_count = c, dispute_count = d,
         status = CASE
           WHEN status = 'official' THEN 'official'
           WHEN d >= 3 AND d > c THEN 'declared'
           WHEN c >= 3 THEN 'confirmed'
           ELSE 'declared' END
   WHERE id = p_zone RETURNING * INTO z;
  RETURN z;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.zones_near(p_lat double precision, p_lng double precision, p_radius_m double precision DEFAULT 8000, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(id uuid, source_app text, event_id uuid, kind text, label text, note text, severity integer, starts_at timestamp with time zone, ends_at timestamp with time zone, created_by uuid, confirm_count integer, dispute_count integer, status text, geojson text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT z.id, z.source_app, z.event_id, z.kind, z.label, z.note, z.severity,
         z.starts_at, z.ends_at, z.created_by, z.confirm_count, z.dispute_count,
         z.status, ST_AsGeoJSON(z.geom) AS geojson
  FROM public.map_zones z
  WHERE z.status NOT IN ('removed','expired')
    AND z.ends_at > p_at
    AND z.starts_at < p_at + interval '14 days'
    AND ST_DWithin(z.geom::geography,
          ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
          GREATEST(100, LEAST(50000, COALESCE(p_radius_m, 8000))))
  ORDER BY z.starts_at
  LIMIT 500;
$function$;
